INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A financial institution needs to integrate a generative AI solution for internal report summarization. The solution must handle sensitive data, require minimal infrastructure management, and allow for rapid prototyping. The primary constraint is to achieve the LEAST operational overhead while ensuring data security. Which architectural approach should a solutions architect recommend?', '["Utilize Amazon Bedrock with AWS KMS for encryption and AWS PrivateLink for secure network access.","Deploy a self-managed large language model on Amazon EC2 instances within a private VPC.","Use Amazon SageMaker to host a fine-tuned open-source model, managing its lifecycle manually.","Implement a custom API Gateway endpoint that invokes an AWS Lambda function to call an external GenAI service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages Amazon Bedrock, a fully managed service that provides access to foundation models without managing any underlying infrastructure, thus ensuring the LEAST operational overhead. Integrating with AWS Key Management Service (AWS KMS) provides robust encryption for sensitive data, and AWS PrivateLink ensures secure, private network connectivity. Option B (incorrect) involves self-managing EC2 instances, which significantly increases operational overhead due to patching, scaling, and maintenance. Option C (incorrect) requires managing the SageMaker endpoint and model lifecycle, which, while managed, still incurs more operational overhead than Bedrock for foundational model access. Option D (incorrect) introduces dependency on an external GenAI service and requires managing API Gateway and Lambda, potentially increasing complexity and operational overhead compared to a fully integrated AWS service like Bedrock.', 64, 'm_64_1', 1, NULL, NULL),
  ('mock_64_all_1775003892874', 'A media company wants to generate personalized marketing copy using a large language model. They need a solution that allows for easy experimentation with different models and prompt variations, while ensuring all model interactions are logged for compliance. The key requirement is to minimize the time-to-market for new marketing campaigns. Which AWS service combination best supports this goal?', '["Amazon SageMaker for model hosting, AWS Step Functions for prompt orchestration, and Amazon CloudWatch for logging.","Amazon Bedrock for foundation model access, AWS Lambda for prompt invocation, and Amazon CloudWatch Logs for auditing.","Amazon EC2 instances with custom model deployments, AWS Batch for inference, and Amazon S3 for log storage.","AWS Glue for data preparation, Amazon Athena for querying model outputs, and AWS WAF for security."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon Bedrock, which offers a wide range of foundation models and simplifies model experimentation by providing a unified API. AWS Lambda can be used to invoke these models and manage prompt variations, offering serverless scalability. Amazon CloudWatch Logs automatically captures all Lambda invocations and Bedrock interactions, ensuring compliance logging with minimal configuration. This combination minimizes operational overhead and speeds up time-to-market. Option A (incorrect) involves SageMaker, which is powerful but requires more management than Bedrock for simply accessing FMs, and Step Functions might be overkill for simple prompt orchestration. Option C (incorrect) requires significant infrastructure management (EC2, Batch, S3 for logs), increasing operational overhead and time-to-market. Option D (incorrect) focuses on data analytics and security rather than direct GenAI model interaction and prompt experimentation, making it unsuitable for the core requirement.', 64, 'm_64_1', 2, NULL, NULL),
  ('mock_64_all_1775003892874', 'An e-commerce company plans to implement a chatbot for customer support, leveraging generative AI to provide more natural and helpful responses. The solution needs to scale automatically with demand, integrate with existing customer data in Amazon DynamoDB, and maintain high availability. The MOST critical constraint is to ensure a highly responsive user experience. Which architecture meets these requirements?', '["AWS AppSync with a custom resolver calling a self-hosted model on Amazon EC2.","Amazon API Gateway with AWS Lambda functions invoking Amazon SageMaker endpoints for inference.","Amazon Lex for conversational interface, integrated with AWS Lambda and Amazon Bedrock for generative responses.","Amazon Connect for contact center, using Amazon Kinesis for data streaming to a batch inference system."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a highly responsive and scalable solution. Amazon Lex is a fully managed service for building conversational interfaces, automatically handling speech-to-text and natural language understanding. It can seamlessly integrate with AWS Lambda to orchestrate business logic and interact with Amazon Bedrock for generative AI responses, ensuring low latency and high availability. This serverless architecture scales automatically with demand. Option A (incorrect) involves self-hosting a model on EC2, which requires manual scaling and management, potentially leading to higher latency and operational overhead. Option B (incorrect) uses SageMaker endpoints, which can be responsive, but Lex offers a more integrated and managed conversational AI experience. Option D (incorrect) is more suited for contact center operations and batch processing, not real-time, highly responsive chatbot interactions.', 64, 'm_64_1', 3, NULL, NULL);

