INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A global e-commerce platform needs to implement a product recommendation system using semantic search. The system must store millions of product embeddings, support high-throughput queries with low latency, and allow for flexible metadata filtering. The MOST important constraint is to ensure query performance and scalability. Which vector store solution is most appropriate?', '["Amazon OpenSearch Service with the k-NN plugin for vector search and rich metadata support.","Amazon Aurora PostgreSQL with the pgvector extension, deployed on a single large instance.","Amazon DynamoDB for storing metadata, with embeddings stored in Amazon S3 and processed by AWS Lambda.","A self-managed FAISS index deployed on Amazon EC2 instances with manual scaling and replication."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is ideal for high-throughput, low-latency semantic search with metadata filtering. Amazon OpenSearch Service is a managed service that offers scalability, high availability, and integrates the k-NN plugin for efficient vector search. It natively supports storing and querying rich metadata alongside embeddings, making it perfect for complex filtering requirements and ensuring query performance and scalability. Option B (incorrect) might struggle with millions of embeddings on a single instance for high-throughput, low-latency queries, and scaling Aurora for vector search can be more complex than OpenSearch. Option C (incorrect) introduces significant latency and complexity by separating embeddings and metadata across different services and requiring Lambda for processing, which is not suitable for real-time semantic search. Option D (incorrect) involves a self-managed solution on EC2, which would require significant operational overhead for scaling, high availability, and maintenance, failing the managed service benefit.', 64, 'm_64_4', 4, NULL, NULL),
  ('mock_64_all_1775003892874', 'A content management system requires a vector database to power a RAG-based content summarization tool. The solution needs to store document embeddings, support real-time updates to the underlying content, and integrate seamlessly with AWS services. The primary goal is to minimize development effort and operational complexity. Which AWS service provides the LEAST operational overhead for this task?', '["Amazon OpenSearch Service with k-NN plugin, requiring manual index management.","Amazon Bedrock Knowledge Bases, which automatically handles chunking, embedding, and vector storage.","Amazon Aurora PostgreSQL with pgvector, managed by an internal database administration team.","A custom vector store built on Amazon S3 and AWS Lambda, requiring extensive custom code."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) offers the LEAST operational overhead. Amazon Bedrock Knowledge Bases is a fully managed service that automates the entire process of preparing data for RAG, including document chunking, generating embeddings using a chosen Bedrock embedding model, and storing them in a managed vector store (e.g., Amazon OpenSearch Service or Pinecone). It also handles real-time synchronization with data sources like Amazon S3, minimizing development effort and operational complexity. Option A (incorrect) requires manual management of OpenSearch indexes and data ingestion, increasing operational overhead. Option C (incorrect) requires managing an Aurora database, even if it''s a managed service, it still involves more configuration and operational tasks than a fully integrated RAG solution like Bedrock Knowledge Bases. Option D (incorrect) would involve significant development effort and custom code for all aspects of the vector store, directly contradicting the goal of minimizing effort and complexity.', 64, 'm_64_4', 5, NULL, NULL),
  ('mock_64_all_1775003892874', 'A startup is developing an AI-powered customer service agent that uses a RAG architecture. They need a cost-effective vector store for storing customer interaction embeddings, with the ability to scale as their user base grows. The solution must also support efficient similarity search. The primary constraint is to minimize infrastructure costs for a rapidly evolving product. Which approach is MOST cost-effective initially?', '["Deploying a dedicated Amazon OpenSearch Service cluster with provisioned capacity.","Using Amazon Aurora PostgreSQL with pgvector on a serverless configuration.","Implementing Amazon Bedrock Knowledge Bases with a fully managed vector store.","Storing embeddings in Amazon S3 and using AWS Lambda for on-demand vector calculations."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the MOST cost-effective initially for a rapidly evolving product with potentially unpredictable usage patterns. Storing embeddings in Amazon S3 is extremely low-cost, and using AWS Lambda for on-demand vector calculations (e.g., loading a subset of embeddings into memory for a query) allows for a pay-per-use model, minimizing idle infrastructure costs. This approach provides flexibility to scale as needed without upfront provisioning. Option A (incorrect) involves a dedicated OpenSearch cluster, which has a higher baseline cost due to provisioned capacity. Option B (incorrect) Aurora Serverless with pgvector is more cost-effective than provisioned, but still generally more expensive than S3+Lambda for initial, potentially low-volume use cases. Option C (incorrect) Amazon Bedrock Knowledge Bases is a fully managed, convenient option, but its cost structure might be higher than a bare-bones S3+Lambda approach for a startup prioritizing minimal initial infrastructure costs.', 64, 'm_64_4', 6, NULL, NULL);

