INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A legal firm is building a RAG application to answer complex legal queries from a vast repository of case law documents. The system needs to accurately retrieve relevant passages, even when queries are ambiguous or require deep contextual understanding. The primary objective is to maximize retrieval precision and recall for specialized legal terminology. Which retrieval mechanism is MOST effective?', '["Hybrid search combining keyword (BM25) and semantic (vector) search, followed by a re-ranking model.","Pure vector similarity search using only cosine similarity on document embeddings.","Simple keyword search using Amazon OpenSearch Service''s default full-text capabilities.","Pre-filtering documents based on broad categories before performing a basic vector search."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the MOST effective for maximizing retrieval precision and recall, especially for complex, specialized domains like legal research. Hybrid search combines the strengths of keyword search (like BM25) for exact term matching and semantic (vector) search for conceptual understanding, ensuring both precise hits and contextually relevant results. A subsequent re-ranking model (e.g., using Amazon Bedrock''s re-rankers) further refines the results by considering the query and retrieved passages together, significantly improving relevance. Option B (incorrect) pure vector search might miss exact keyword matches crucial in legal contexts and can struggle with very specific, rare terms. Option C (incorrect) simple keyword search lacks the semantic understanding needed for ambiguous queries and deep contextual retrieval. Option D (incorrect) pre-filtering can reduce the search space but doesn''t inherently improve the quality of the actual search or re-ranking process for complex queries.', 64, 'm_64_5', 7, NULL, NULL),
  ('mock_64_all_1775003892874', 'An education technology company is developing an AI tutor that provides personalized learning content. The RAG system needs to retrieve information from textbooks and articles, and then re-rank the results based on relevance to the student''s specific question. The key requirement is to improve the quality of retrieved information presented to the generative model. Which strategy should be employed?', '["Only use a basic vector similarity search to retrieve the top-N documents.","Implement a re-ranking step using a specialized model (e.g., Amazon Bedrock''s Cohere Rerank) after initial retrieval.","Increase the number of retrieved documents significantly to ensure all relevant information is included.","Perform a simple keyword search and pass all results directly to the generative model."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the key requirement of improving the quality of retrieved information. A re-ranking step, often powered by a more sophisticated cross-encoder model (like those available through Amazon Bedrock''s Cohere Rerank), takes the initial retrieved documents and the original query, then scores their relevance more accurately than the initial retrieval model. This ensures that the most pertinent information is presented to the generative model, leading to higher quality and more accurate responses. Option A (incorrect) a basic vector search might return semantically similar but not precisely relevant documents. Option C (incorrect) increasing the number of documents can introduce noise and exceed the generative model''s context window, potentially degrading performance. Option D (incorrect) a simple keyword search lacks semantic understanding and would likely provide low-quality, less relevant information to the generative model.', 64, 'm_64_5', 8, NULL, NULL),
  ('mock_64_all_1775003892874', 'A marketing agency wants to generate creative ad copy by augmenting a foundation model with their brand guidelines and past campaign data. The data is stored in various formats, including PDFs and text files. The solution needs to efficiently process these documents into embeddings for retrieval. The primary constraint is to ensure consistent and effective data preparation for RAG. Which approach is best for document chunking and embedding?', '["Manually chunking documents into fixed-size segments and using a custom embedding model on Amazon EC2.","Using AWS Glue DataBrew for text extraction and then a custom Python script to chunk and embed.","Leveraging Amazon Bedrock Knowledge Bases to automatically handle document chunking, embedding, and synchronization.","Storing entire documents in Amazon S3 and passing them directly to the embedding model without chunking."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best approach for consistent and effective data preparation with minimal operational overhead. Amazon Bedrock Knowledge Bases is a fully managed service that automates the entire RAG data pipeline, including ingesting documents from various sources (like Amazon S3), intelligently chunking them, generating embeddings using a chosen Bedrock embedding model (e.g., Amazon Titan Embeddings), and storing them in a vector database. This ensures consistency and reduces manual effort significantly. Option A (incorrect) involves manual chunking and a self-managed EC2 model, which is highly labor-intensive and prone to inconsistencies. Option B (incorrect) requires custom scripting for chunking and embedding, adding development and maintenance overhead. Option D (incorrect) passing entire documents without chunking is inefficient, can exceed embedding model input limits, and makes retrieval less precise, as the model might retrieve large, irrelevant sections.', 64, 'm_64_5', 9, NULL, NULL),
  ('mock_64_all_1775003892874', 'A customer support department is implementing a RAG-powered chatbot to answer frequently asked questions. The chatbot needs to provide concise and accurate answers by retrieving information from a knowledge base. To handle diverse user queries, the system must be able to break down complex questions into simpler sub-queries. Which retrieval enhancement technique should be utilized?', '["Implementing a simple keyword search for all queries.","Using a re-ranking model to prioritize retrieved documents based on initial similarity scores.","Increasing the size of document chunks to capture more context in each retrieval.","Employing query decomposition to break down complex user questions into multiple simpler sub-queries."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) directly addresses the need to handle diverse and complex user queries by breaking them down. Query decomposition is a retrieval enhancement technique where a complex user question is transformed into several simpler, more focused sub-queries. Each sub-query can then be used to retrieve relevant information independently, and the results are combined before being passed to the generative model. This improves the chances of retrieving comprehensive and accurate information for multi-faceted questions. Option A (incorrect) simple keyword search is insufficient for complex queries. Option B (incorrect) re-ranking improves the order of already retrieved documents but doesn''t help in cases where the initial retrieval failed due to query complexity. Option C (incorrect) increasing chunk size can lead to less precise retrieval and potentially exceed the model''s context window, making it harder for the model to identify the most relevant information.', 64, 'm_64_5', 10, NULL, NULL);

