INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A media company is processing user-generated content, including text and images, to feed into a multimodal generative AI model for content moderation. The pipeline must validate data quality, extract entities from text, and resize images to model-compatible dimensions. The primary goal is to ensure high-quality, normalized input for the foundation model with minimal manual intervention. Which AWS services should be combined?', '["AWS Lambda for orchestration, Amazon Comprehend for text entity extraction, and Amazon Rekognition for image processing.","AWS Glue for data transformation, Amazon Textract for text extraction, and a custom script on Amazon EC2 for image resizing.","Amazon Kinesis for streaming data, Amazon SageMaker Processing for multimodal data validation, and Amazon S3 for storage.","AWS Step Functions for workflow management, Amazon Transcribe for audio processing, and Amazon Sagemaker Ground Truth for labeling."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a serverless, managed solution for multimodal data processing with minimal manual intervention. AWS Lambda can orchestrate the pipeline, triggering on new content. Amazon Comprehend is a natural language processing (NLP) service that can extract entities and key phrases from text. Amazon Rekognition is a computer vision service capable of analyzing images, including detecting objects and faces, and can be used to validate image quality or dimensions, or trigger resizing operations via Lambda. This combination ensures high-quality, normalized input efficiently. Option B (incorrect) involves a custom script on EC2, increasing operational overhead. Amazon Textract is primarily for text from documents, not general text entity extraction. Option C (incorrect) SageMaker Processing is suitable for large-scale data processing but might be overkill for simple entity extraction and image resizing, potentially increasing complexity. Option D (incorrect) Amazon Transcribe is for audio, and SageMaker Ground Truth is for data labeling, neither directly addresses the core requirements of text entity extraction and image resizing for multimodal input.', 64, 'm_64_3', 11, NULL, NULL),
  ('mock_64_all_1775003892874', 'A healthcare provider needs to extract structured medical information from clinical notes (unstructured text) before feeding it to a generative AI model for research. The pipeline must identify medical entities like conditions, medications, and procedures, and then convert the output into a consistent JSON format. The key requirement is to accurately transform unstructured data into a structured format. Which AWS service is best suited for this task?', '["Amazon Textract for extracting text from scanned clinical notes.","Amazon Comprehend Medical for specialized medical entity extraction and relationship detection.","AWS Glue DataBrew for data profiling and cleaning of structured data.","Amazon SageMaker for training a custom NLP model to extract entities."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is specifically designed for this use case. Amazon Comprehend Medical is a specialized natural language processing (NLP) service that accurately extracts medical information from unstructured text, such as clinical notes. It can identify entities like medical conditions, medications, dosages, and procedures, and also detect relationships between them. The output can be easily consumed and transformed into a consistent JSON format, meeting the key requirement to accurately transform unstructured data into a structured format. Option A (incorrect) Amazon Textract is for extracting text from documents (e.g., PDFs, images) but does not perform medical entity extraction. Option C (incorrect) AWS Glue DataBrew is for visual data preparation of structured and semi-structured data, not for deep NLP on unstructured medical text. Option D (incorrect) Amazon SageMaker could be used to train a custom NLP model, but this would require significant development effort and expertise, whereas Comprehend Medical provides a pre-trained, managed solution.', 64, 'm_64_3', 12, NULL, NULL),
  ('mock_64_all_1775003892874', 'An automotive manufacturer collects telemetry data from vehicles, which includes sensor readings (tabular) and event logs (text). This data needs to be preprocessed and formatted for a generative AI model to predict maintenance needs. The pipeline must handle large volumes of streaming data, perform data quality checks, and normalize values. The primary constraint is to ensure real-time data ingestion and processing. Which architecture is most suitable?', '["AWS DataSync for batch data transfer to Amazon S3, followed by AWS Glue for processing.","Amazon SQS for message queuing, AWS Lambda for processing, and Amazon DynamoDB for storage.","Amazon Kinesis Data Streams for ingestion, AWS Lambda for real-time processing and validation, and Amazon S3 for raw and processed data storage.","AWS Transfer Family for secure file transfer, Amazon Redshift for data warehousing, and Amazon QuickSight for visualization."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable architecture for real-time data ingestion and processing of large volumes of streaming data. Amazon Kinesis Data Streams provides a highly scalable and durable way to ingest streaming data. AWS Lambda can then be triggered in real-time by Kinesis to perform immediate processing, data quality checks, normalization, and formatting before storing the raw and processed data in Amazon S3 for further use by the generative AI model. Option A (incorrect) AWS DataSync and AWS Glue are primarily for batch processing, not real-time streaming. Option B (incorrect) Amazon SQS is a message queue, not optimized for high-throughput streaming data ingestion like Kinesis, and DynamoDB might not be the best fit for large volumes of raw telemetry data. Option D (incorrect) AWS Transfer Family is for file transfer, Redshift for data warehousing, and QuickSight for visualization; this combination is not designed for real-time streaming data preprocessing for GenAI.', 64, 'm_64_3', 13, NULL, NULL),
  ('mock_64_all_1775003892874', 'An online retailer wants to use a generative AI model to create product descriptions from product specifications, which are often incomplete or inconsistent. The data processing pipeline needs to identify missing values, correct common errors, and enrich the data before it''s sent to the model. The primary goal is to improve the quality and completeness of the input data. Which AWS service can best achieve this?', '["Amazon Comprehend for sentiment analysis and key phrase extraction.","Amazon Rekognition for image and video analysis to enrich product data.","AWS Lambda for custom scripting to perform basic data cleaning and formatting.","AWS Glue Data Quality for defining rules, detecting anomalies, and improving data quality."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is specifically designed to improve the quality and completeness of data. AWS Glue Data Quality allows users to define rules and checks to identify missing values, detect anomalies, and enforce data quality standards directly within their data pipelines. It provides a managed way to assess, monitor, and improve the reliability and accuracy of data, which is crucial for ensuring high-quality input for generative AI models. Option A (incorrect) Amazon Comprehend is for text analysis, not general data quality assessment and correction. Option B (incorrect) Amazon Rekognition is for image/video analysis, not relevant for improving product specification data quality. Option C (incorrect) AWS Lambda can run custom scripts, but for comprehensive data quality management, a dedicated service like AWS Glue Data Quality provides a more robust, scalable, and managed solution than custom code.', 64, 'm_64_3', 14, NULL, NULL);

