INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A customer support organization is deploying a generative AI chatbot for first-line support. They need to ensure that the chatbot''s responses are always helpful, on-topic, and adhere to company policies, avoiding harmful or inappropriate content. The primary constraint is to enforce strict content moderation and safety guidelines for all AI-generated responses. Which AWS service is designed for this purpose?', '["Amazon Bedrock Guardrails, configured with specific content policies and denied topics.","AWS WAF (Web Application Firewall) to filter incoming user requests to the chatbot.","Amazon Comprehend for detecting personally identifiable information (PII) in responses.","AWS Identity and Access Management (IAM) policies to restrict model access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is precisely designed for enforcing content moderation and safety guidelines for generative AI interactions. Amazon Bedrock Guardrails allows users to define custom content policies, specify sensitive topics to be filtered, and set thresholds for harmful content categories (e.g., hate speech, insults, sexual content). It acts as a layer between the user and the foundation model, ensuring that both user inputs and model outputs adhere to defined safety standards. Option B (incorrect) AWS WAF protects web applications from common web exploits but is not designed for content moderation of AI-generated text. Option C (incorrect) Amazon Comprehend can detect PII, which is a part of content safety, but Guardrails provides a much broader and more integrated solution for enforcing comprehensive content policies. Option D (incorrect) IAM policies control access to AWS resources but do not moderate the content generated by AI models.', 64, 'm_64_6', 15, NULL, NULL),
  ('mock_64_all_1775003892874', 'A development team is building a GenAI application that requires complex, multi-step reasoning from a foundation model to solve user problems. The prompts involve breaking down a problem, performing intermediate steps, and then synthesizing a final answer. The key requirement is to guide the model through a logical thought process to improve accuracy and reduce hallucinations. Which prompt engineering strategy should be applied?', '["Zero-shot prompting, providing only the task description without examples.","Chain-of-Thought (CoT) prompting, instructing the model to show its reasoning steps.","Few-shot prompting, providing a small number of input-output examples.","Role-play prompting, assigning a specific persona to the foundation model."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective prompt engineering strategy for guiding a foundation model through complex, multi-step reasoning. Chain-of-Thought (CoT) prompting explicitly instructs the model to articulate its intermediate reasoning steps before providing a final answer. This process makes the model''s thought process transparent, improves its ability to break down problems, and significantly enhances accuracy while reducing hallucinations for complex tasks. Option A (incorrect) Zero-shot prompting is suitable for simpler tasks but lacks the guidance needed for complex reasoning. Option C (incorrect) Few-shot prompting provides examples but doesn''t explicitly force the model to show its reasoning process, which is critical for complex tasks. Option D (incorrect) Role-play prompting helps in setting the tone or style of the response but does not inherently improve the model''s multi-step reasoning capabilities.', 64, 'm_64_6', 16, NULL, NULL),
  ('mock_64_all_1775003892874', 'A marketing team uses a generative AI model to create various types of content, such as blog posts, social media updates, and email newsletters. They need a way to manage and version control their prompts, collaborate on prompt design, and ensure consistency across different campaigns. The primary goal is to streamline prompt development and governance. Which AWS service provides these capabilities?', '["Amazon S3 for storing prompt templates as text files.","AWS CodeCommit for version controlling prompt code snippets.","Amazon Bedrock Prompt Management, offering a centralized repository for prompt templates and versioning.","AWS Systems Manager Parameter Store for storing prompt variables and configurations."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed for streamlining prompt development and governance. Amazon Bedrock Prompt Management provides a centralized, managed repository for creating, organizing, versioning, and testing prompt templates. It facilitates collaboration among teams, allows for A/B testing of different prompts, and ensures consistency across various generative AI applications and campaigns, directly addressing the stated requirements. Option A (incorrect) storing prompts in Amazon S3 is possible but lacks versioning, collaboration features, and a structured management interface. Option B (incorrect) AWS CodeCommit is a source control service for code, not specifically optimized for managing and versioning prompt templates in a user-friendly way for non-developers. Option D (incorrect) AWS Systems Manager Parameter Store is for storing configuration data and secrets, not for managing complex prompt templates with versioning and collaboration features.', 64, 'm_64_6', 17, NULL, NULL),
  ('mock_64_all_1775003892874', 'An enterprise is implementing a GenAI application for internal knowledge retrieval. They need to ensure that the AI model maintains context across multiple turns of a conversation with a user, providing coherent and relevant follow-up responses. The primary constraint is to maintain conversation state effectively for a natural user experience. Which approach is most suitable for managing conversation state?', '["Re-sending the entire conversation history with each new user prompt to the foundation model.","Using a stateless API Gateway and AWS Lambda function for each turn, discarding previous context.","Storing conversation history in a persistent data store like Amazon DynamoDB and retrieving it for each turn.","Implementing a short-term memory cache in the client-side application to hold recent interactions."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) is the most suitable approach for effectively managing conversation state in a GenAI application. Storing conversation history in a persistent, highly available data store like Amazon DynamoDB allows the application to retrieve the full context for each new user turn. This ensures that the foundation model receives all necessary previous interactions to generate coherent and relevant follow-up responses, providing a natural user experience. Option A (incorrect) re-sending the entire conversation history can quickly exceed token limits for longer conversations and increase inference costs. Option B (incorrect) using a stateless approach discards context, leading to disjointed and irrelevant responses. Option D (incorrect) implementing a client-side cache is unreliable for maintaining server-side conversation state, especially across different devices or sessions, and doesn''t scale for enterprise-level applications.', 64, 'm_64_6', 18, NULL, NULL);

