INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A data science team is evaluating several foundation models on Amazon Bedrock for a text summarization task. They need to compare model performance, latency, and cost-effectiveness across different models and providers before making a final selection. The primary goal is to choose the optimal model based on quantitative metrics. Which AWS service combination supports this evaluation process?', '["AWS Step Functions for orchestrating model calls, Amazon CloudWatch for metrics, and Amazon S3 for storing evaluation results.","Amazon SageMaker Model Registry for tracking model versions, AWS Lambda for inference, and Amazon DynamoDB for results.","AWS Glue DataBrew for data preparation, Amazon Athena for querying logs, and Amazon QuickSight for visualization.","Amazon Kinesis Data Firehose for streaming data, Amazon Redshift for analytics, and AWS Cost Explorer for cost analysis."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides a robust and scalable solution for evaluating foundation models. AWS Step Functions can orchestrate the calls to different Amazon Bedrock models, allowing for parallel execution and management of complex evaluation workflows. Amazon CloudWatch can collect metrics (latency, error rates) from these invocations, and custom metrics can be pushed for performance. Amazon S3 serves as a cost-effective and scalable storage for raw evaluation data, model outputs, and aggregated results, enabling comprehensive analysis to choose the optimal model. Option B (incorrect) SageMaker Model Registry is for custom models, not directly for evaluating Bedrock FMs. Lambda for inference is fine, but DynamoDB might not be the best for large-scale evaluation results. Option C (incorrect) focuses on data preparation and visualization, not direct orchestration and metric collection for model evaluation. Option D (incorrect) is more for general data analytics and cost management, not specifically tailored for comparing GenAI model performance and latency.', 64, 'm_64_2', 19, NULL, NULL),
  ('mock_64_all_1775003892874', 'A startup is developing a GenAI application and wants to ensure business continuity even if a specific foundation model or provider experiences an outage. They need the ability to seamlessly switch to an alternative model or provider without significant application downtime. The key requirement is to build a resilient GenAI architecture. Which strategy should be implemented?', '["Hardcode the preferred foundation model endpoint in the application code and manually update it during an outage.","Implement a dynamic model routing layer that selects models based on availability and performance metrics.","Deploy the application in a single AWS Region and rely on AWS''s inherent regional resilience.","Use a single foundation model provider and assume high availability will prevent any service interruptions."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective strategy for building a resilient GenAI architecture. Implementing a dynamic model routing layer (e.g., using AWS Lambda or a custom service) allows the application to abstract away the specific foundation model or provider. This layer can monitor the health and performance of multiple models/providers and automatically route requests to an available and performing alternative in case of an outage or degradation, ensuring seamless switching and business continuity. Option A (incorrect) hardcoding endpoints and manual updates would lead to significant downtime during an outage. Option C (incorrect) deploying in a single region does not protect against outages of a specific foundation model or provider, even if the region itself is resilient. Option D (incorrect) relying on a single provider''s high availability without a fallback mechanism is a single point of failure and does not guarantee business continuity during an outage.', 64, 'm_64_2', 20, NULL, NULL),
  ('mock_64_all_1775003892874', 'A company has developed a custom foundation model using Amazon SageMaker and needs to manage its lifecycle, including versioning, deployment, and rollback capabilities. They also want to ensure that the model can be easily discovered and reused by other teams within the organization. The primary objective is to establish robust governance and MLOps practices for their custom models. Which AWS service provides these capabilities?', '["Amazon S3 for storing model artifacts and manual versioning through file naming conventions.","AWS CodePipeline for automating CI/CD pipelines for application code, not ML models.","AWS Systems Manager Parameter Store for storing model endpoint configurations and basic metadata.","Amazon SageMaker Model Registry for cataloging, versioning, and managing model deployment and approval workflows."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is specifically designed to establish robust governance and MLOps practices for custom models. Amazon SageMaker Model Registry provides a centralized repository to catalog, version, and manage machine learning models. It supports tracking model lineage, managing model deployment and approval workflows, and facilitating model discovery and reuse across different teams, directly addressing the company''s objectives. Option A (incorrect) storing models in Amazon S3 with manual naming conventions lacks the structured metadata, approval workflows, and governance features required for robust MLOps. Option B (incorrect) AWS CodePipeline is for application code CI/CD, not directly for ML model lifecycle management. Option C (incorrect) AWS Systems Manager Parameter Store can store configurations but is not a full-fledged model registry with versioning, lineage, and deployment capabilities.', 64, 'm_64_2', 21, NULL, NULL);

