INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A financial services company is developing a generative AI application using Amazon Bedrock for customer support. Due to strict regulatory requirements, all interactions with the foundational models must be logged for audit purposes, including prompts and responses. The solution needs to ensure traceability and compliance with minimal operational overhead. Which approach best meets these requirements?', '["Enable Amazon Bedrock Model Invocation Logging to Amazon CloudWatch Logs and Amazon S3.","Implement a custom AWS Lambda function to intercept and log all API calls to Amazon Bedrock.","Configure Amazon CloudTrail to log all Amazon Bedrock API calls, then send logs to Amazon S3.","Develop a client-side logging mechanism within the application to capture prompts and responses before sending to Bedrock."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirement for logging prompts and responses for audit and compliance with minimal operational overhead. Amazon Bedrock Model Invocation Logging is specifically designed for this purpose, capturing detailed input and output payloads and delivering them to Amazon CloudWatch Logs and Amazon S3. This is a native, managed feature. Option B (incorrect) would introduce significant operational overhead and complexity, as it requires developing, deploying, and maintaining a custom AWS Lambda function to intercept and parse Bedrock API calls, which is less efficient than the native logging. Option C (incorrect) is useful for auditing API calls (who called what API), but Amazon CloudTrail does not capture the full prompt and response payloads of model invocations, which are critical for generative AI audit requirements. Option D (incorrect) shifts the logging responsibility to the client application, which is less secure, prone to tampering, and difficult to enforce consistently across different client interfaces, making it unsuitable for strict regulatory compliance.', 66, 'm_66_3', 1, NULL, NULL),
  ('mock_64_all_1775003892874', 'A healthcare provider is building an Amazon Bedrock-powered application to summarize patient records for doctors. To ensure the generated summaries are accurate and do not contain fabricated information, the company needs a mechanism to reduce hallucinations by ensuring responses are based solely on provided medical documents. Which Amazon Bedrock feature should be implemented to achieve this goal?', '["Utilize Amazon CloudWatch metrics to monitor model output consistency.","Implement Amazon Bedrock Guardrails with grounding to a knowledge base of medical documents.","Configure AWS IAM policies to restrict the foundational model''s access to external data sources.","Develop a post-processing AWS Lambda function to cross-reference generated summaries with original documents."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and managed solution for hallucination mitigation by ensuring responses are based on specific data. Amazon Bedrock Guardrails with grounding allows you to connect a knowledge base (like medical documents) and instruct the model to only use information from that source, significantly reducing the likelihood of hallucinations. Option A (incorrect) focuses on monitoring metrics, which can indicate issues but does not actively prevent hallucinations or ensure grounding. Option C (incorrect) restricts model access to external data, but it doesn''t provide a mechanism to explicitly ground responses to *provided* documents, nor does it prevent the model from generating information not present in its training data if not explicitly instructed to use a specific knowledge base. Option D (incorrect) involves developing a custom AWS Lambda function for post-processing, which adds significant operational overhead and complexity, and is less efficient and robust than native Bedrock Guardrails for grounding.', 66, 'm_66_3', 2, NULL, NULL),
  ('mock_64_all_1775003892874', 'A media company uses Amazon Bedrock to generate marketing copy. They need to ensure that the generated content adheres to brand guidelines and avoids specific sensitive keywords or phrases. Additionally, they must prevent the model from discussing off-topic subjects unrelated to marketing. The solution should be easy to manage and apply consistently across various marketing campaigns. Which Bedrock feature is best suited for this requirement?', '["Rely on the foundational model''s inherent safety capabilities and fine-tune it with brand guidelines.","Implement a custom content moderation service using Amazon Comprehend and AWS Lambda.","Configure Amazon Bedrock Guardrails with content filters and topic denial policies.","Use AWS IAM policies to restrict the types of prompts that can be sent to the foundational model."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly addresses the need for content filtering, keyword avoidance, and topic denial in a managed and consistent manner. Amazon Bedrock Guardrails allows defining explicit content filters for harmful categories, custom word filters for specific keywords/phrases, and topic denial policies to prevent discussions on off-topic subjects. This is a purpose-built feature for such controls. Option A (incorrect) relies on the model''s inherent capabilities, which are not guaranteed to enforce specific brand guidelines or prevent off-topic discussions reliably without explicit controls, and fine-tuning is for adapting model behavior, not for runtime content moderation. Option B (incorrect) involves building a custom solution with Amazon Comprehend and AWS Lambda, which would increase operational overhead and complexity compared to the native, managed Guardrails feature. Option D (incorrect) uses AWS IAM policies, which control access to Bedrock API actions but cannot filter content, deny topics, or enforce specific keywords within the model''s generated output.', 66, 'm_66_3', 3, NULL, NULL),
  ('mock_64_all_1775003892874', 'An e-commerce company uses Amazon Bedrock to power a customer chatbot. To maintain customer trust and comply with data privacy regulations, the company must ensure that no personally identifiable information (PII) from customer inputs or model outputs is inadvertently stored or exposed. The solution should automatically detect and redact PII with minimal development effort. Which approach is most effective?', '["Implement client-side JavaScript to detect and redact PII before sending prompts to Bedrock.","Use AWS Lambda to pre-process prompts and post-process responses with Amazon Macie for PII detection.","Configure Amazon Bedrock Model Invocation Logging to filter out PII before storing logs.","Deploy Amazon Bedrock Guardrails with PII redaction policies for both prompts and model responses."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) provides a managed, effective, and low-effort solution for PII redaction. Amazon Bedrock Guardrails includes built-in capabilities to detect and redact PII from both user inputs (prompts) and model outputs (responses), ensuring sensitive information is not processed or exposed. This is a core feature of Guardrails for safety and privacy. Option A (incorrect) relies on client-side controls, which are easily bypassed, less secure, and not suitable for robust compliance requirements. Option B (incorrect) involves building a custom solution with AWS Lambda and Amazon Macie, which would significantly increase operational overhead, development complexity, and latency compared to the native Guardrails feature. Amazon Macie is primarily for discovering PII in data at rest, not for real-time redaction in a generative AI workflow. Option C (incorrect) focuses on logging, but Model Invocation Logging captures the full payload by default; it does not filter or redact PII before logging without additional mechanisms, and its primary purpose is audit, not real-time PII protection during inference.', 66, 'm_66_3', 4, NULL, NULL),
  ('mock_64_all_1775003892874', 'A global enterprise is integrating Amazon Bedrock into its internal knowledge management system. The enterprise has strict internal governance policies requiring that all generative AI interactions are auditable and that access to foundational models is tightly controlled based on user roles and departments. The solution must ensure secure and compliant access with granular permissions. Which combination of services should be used?', '["AWS IAM for model access control and Amazon Bedrock Model Invocation Logging for audit trails.","Amazon CloudWatch for monitoring model usage and AWS PrivateLink for secure network access.","Amazon S3 for storing model outputs and AWS Key Management Service (AWS KMS) for encryption.","AWS Organizations for account management and Amazon Cognito for user authentication."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the core requirements for granular access control and comprehensive auditability. AWS IAM allows defining precise permissions for which users or roles can invoke specific Amazon Bedrock models, ensuring access is tightly controlled. Amazon Bedrock Model Invocation Logging captures detailed records of all model interactions, including prompts and responses, which is essential for audit trails and compliance. Option B (incorrect) focuses on monitoring and network access, which are important but do not directly provide granular model access control or detailed invocation audit trails. Option C (incorrect) deals with storage and encryption of outputs, which is a secondary concern to the primary requirements of access control and auditability of the interactions themselves. Option D (incorrect) is for organizational structure and user authentication, which are foundational but do not directly manage access to Bedrock models or log their invocations.', 66, 'm_66_3', 5, NULL, NULL);

