-- Module: m_66_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A government agency is developing a generative AI application using Amazon Bedrock to assist with public inquiries. Due to the sensitive nature of public data, the agency mandates that all PII in user inputs and model outputs must be automatically identified and removed or masked before processing or display. The solution must be highly effective and require minimal custom code. Which Bedrock feature should be utilized?', '["Implement a custom pre-processing AWS Lambda function using regular expressions to detect PII.","Configure Amazon Bedrock Guardrails with PII redaction policies.","Use Amazon Comprehend to detect PII in text, then manually redact it within the application.","Store all inputs and outputs in Amazon S3, then run Amazon Macie periodically to identify PII."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and low-effort solution for automatic PII redaction in real-time generative AI interactions. Amazon Bedrock Guardrails offers built-in PII redaction capabilities that can automatically detect and redact various types of PII from both user prompts and model responses, fulfilling the agency''s mandate with minimal custom code. Option A (incorrect) would require significant development effort to create and maintain a robust PII detection system using regular expressions, which is prone to errors and less comprehensive than a dedicated service. Option C (incorrect) involves Amazon Comprehend for PII detection, but requires manual redaction logic within the application, increasing development complexity and potential for human error. Option D (incorrect) focuses on PII detection in data at rest using Amazon Macie, which is not suitable for real-time redaction during the generative AI inference process.', 66, 'm_66_2', 6, NULL, NULL),
  ('mock_64_all_1775003892874', 'A research institution is using Amazon Bedrock for sensitive scientific data analysis. They require that all API calls to Amazon Bedrock foundational models remain entirely within their Amazon VPC, without traversing the public internet, to meet stringent data privacy and security policies. Which AWS service should be configured to ensure this secure network connectivity?', '["Configure a NAT Gateway within the Amazon VPC for outbound Bedrock API calls.","Use an Internet Gateway with strict Security Group rules for Bedrock API access.","Deploy an AWS PrivateLink VPC Endpoint for Amazon Bedrock.","Establish a VPN connection from the Amazon VPC to the Amazon Bedrock service endpoint."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the standard and most secure way to access AWS services privately from within an Amazon VPC without traversing the public internet. An AWS PrivateLink VPC Endpoint for Amazon Bedrock ensures that all traffic to Bedrock remains within the AWS network, directly addressing the requirement for stringent data privacy and security. Option A (incorrect) uses a NAT Gateway, which allows instances in a private subnet to connect to the internet, but it still involves traffic traversing the public internet to reach Bedrock, violating the ''within their Amazon VPC'' constraint. Option B (incorrect) involves an Internet Gateway, which explicitly routes traffic to and from the public internet, making it unsuitable for this requirement. Option D (incorrect) establishes a VPN connection, typically used for connecting on-premises networks to AWS, not for connecting within AWS to a managed service endpoint privately.', 66, 'm_66_2', 7, NULL, NULL),
  ('mock_64_all_1775003892874', 'A legal firm uses Amazon Bedrock to draft legal summaries, which often contain sensitive client information. The firm requires that all PII is automatically redacted from both prompts and responses, and that every interaction is logged for audit purposes to demonstrate compliance. The solution must be fully managed and minimize custom development. Which combination of Bedrock features meets these requirements?', '["Amazon Bedrock Guardrails with PII redaction and Amazon Bedrock Model Invocation Logging.","AWS PrivateLink for secure access and Amazon CloudWatch for monitoring.","AWS IAM for access control and Amazon S3 for storing redacted outputs.","Custom AWS Lambda functions for PII detection and Amazon CloudTrail for API logging."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses both core requirements using native Amazon Bedrock features. Amazon Bedrock Guardrails with PII redaction automatically handles the detection and masking of sensitive information in real-time for both inputs and outputs. Amazon Bedrock Model Invocation Logging provides a managed way to capture detailed audit trails of all model interactions, including prompts and responses, essential for compliance. Option B (incorrect) focuses on network security and monitoring, which are important but do not provide PII redaction or detailed invocation logging. Option C (incorrect) provides access control and storage, but does not offer automatic PII redaction or comprehensive invocation logging. Option D (incorrect) involves custom AWS Lambda functions, which increases operational overhead and development complexity, contradicting the ''minimal custom development'' constraint, and CloudTrail only logs API calls, not the full prompt/response payloads.', 66, 'm_66_2', 8, NULL, NULL),
  ('mock_64_all_1775003892874', 'A defense contractor is deploying an Amazon Bedrock application for internal intelligence analysis. Due to the highly sensitive nature of the data, all communication with foundational models must be isolated from the public internet and restricted to specific internal networks. The solution must ensure secure, private connectivity. Which AWS service configuration is required?', '["Configure an Internet Gateway and apply strict Network ACLs to the subnets.","Implement an AWS PrivateLink VPC Endpoint for Amazon Bedrock within the contractor''s VPC.","Use a VPN connection from the on-premises network to the Bedrock public endpoint.","Set up a NAT Gateway in a public subnet to route all Bedrock API traffic."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the appropriate solution for ensuring private and secure connectivity to Amazon Bedrock from within an Amazon VPC, without traversing the public internet. An AWS PrivateLink VPC Endpoint for Amazon Bedrock creates a private connection, keeping all traffic within the AWS network and the customer''s VPC. Option A (incorrect) involves an Internet Gateway, which is explicitly for public internet access, violating the isolation requirement. Option C (incorrect) describes a VPN connection, which is typically used for hybrid cloud scenarios (on-premises to AWS) and doesn''t inherently ensure that traffic to Bedrock stays within the AWS network if the Bedrock endpoint itself is public. Option D (incorrect) uses a NAT Gateway, which allows private subnets to initiate outbound connections to the internet, meaning traffic would still traverse the public internet to reach Bedrock.', 66, 'm_66_2', 9, NULL, NULL);

