INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A public relations firm uses Amazon Bedrock to generate press releases. They need to ensure that the generated content avoids offensive language, hate speech, and sexually explicit material, as well as preventing the model from responding to prompts that are off-topic for press releases. The solution must be a managed service that can be easily configured. Which Bedrock feature is best suited?', '["Fine-tune the foundational model with a dataset of appropriate press releases to guide its behavior.","Implement a custom content moderation system using Amazon Rekognition and AWS Lambda.","Configure Amazon Bedrock Guardrails with content filters and topic denial policies.","Use AWS WAF to filter incoming prompts based on keywords before they reach Bedrock."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is specifically designed to address these requirements in a managed and configurable way. Amazon Bedrock Guardrails allows defining content filters for harmful categories (e.g., hate speech, sexual content) and setting up topic denial policies to prevent the model from engaging in off-topic discussions. Option A (incorrect) involves fine-tuning, which can influence model behavior but is not a direct, configurable mechanism for enforcing strict content and topic policies in real-time. Option B (incorrect) suggests using Amazon Rekognition, which is for image and video analysis, not text content moderation, and building a custom system with AWS Lambda would increase operational overhead. Option D (incorrect) uses AWS WAF, which is a web application firewall primarily for protecting web applications from common web exploits, not for content moderation of generative AI prompts and responses.', 66, 'm_66_1', 10, NULL, NULL),
  ('mock_64_all_1775003892874', 'A software development company uses Amazon Bedrock for code generation. Developers often try to ''jailbreak'' the model with malicious prompts to bypass safety filters or extract sensitive information. The company needs a robust, managed solution to detect and prevent such prompt injection attacks. Which Amazon Bedrock feature should be implemented?', '["Implement a custom input validation layer using AWS Lambda to sanitize prompts.","Rely on the foundational model''s built-in safety mechanisms to detect malicious inputs.","Configure Amazon Bedrock Guardrails with prompt injection detection and prevention strategies.","Use AWS Security Hub to monitor for suspicious activity related to Bedrock API calls."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and managed solution for detecting and preventing prompt injection attacks. Amazon Bedrock Guardrails includes specific capabilities for prompt injection detection and prevention, offering a robust defense against attempts to manipulate the model. Option A (incorrect) would require significant custom development and maintenance of an AWS Lambda function, which is less comprehensive and more operationally intensive than a native Guardrails feature. Option B (incorrect) relies solely on the model''s inherent capabilities, which may not be sufficient or configurable enough to counter sophisticated prompt injection attempts. Option D (incorrect) focuses on security monitoring at a broader level, which can alert to suspicious activity but does not actively prevent prompt injection at the model interaction layer.', 66, 'm_66_1', 11, NULL, NULL),
  ('mock_64_all_1775003892874', 'A startup is developing a new generative AI application using Amazon Bedrock for public release. The product team, focused on rapid feature delivery, plans to launch the application without implementing any explicit content moderation or safety controls, assuming the underlying foundational model is sufficient. This approach poses a significant risk to the company''s reputation and user safety. Which anti-pattern does this scenario represent?', '["Over-reliance on custom AWS Lambda functions for content filtering.","Underutilization of AWS IAM for granular access control to foundational models.","Deploying a generative AI application without Bedrock Guardrails in production.","Ignoring the importance of AWS PrivateLink for secure network connectivity."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly describes the anti-pattern: deploying a generative AI application without Bedrock Guardrails in production. This approach is risky because foundational models, even with inherent safety features, can still generate harmful, off-topic, or PII-leaking content, or be manipulated by prompt injection, leading to reputational damage and safety issues. Amazon Bedrock Guardrails provides a multi-layer protection independent of the underlying model. Option A (incorrect) describes a potential architectural choice, not a fundamental anti-pattern related to the absence of safety controls. Option B (incorrect) relates to access control, which is important for security but not the primary concern highlighted in the scenario regarding content moderation and safety. Option D (incorrect) relates to network security, which is also important but not the direct anti-pattern of neglecting content and safety controls for generative AI outputs.', 66, 'm_66_1', 12, NULL, NULL),
  ('mock_64_all_1775003892874', 'An educational platform uses Amazon Bedrock to create personalized learning content. To maintain a safe learning environment, the platform needs to prevent the generation of content containing specific inappropriate words or phrases, and also ensure that any PII accidentally included in prompts by students is automatically removed from the model''s processing. Which Bedrock features should be combined?', '["Amazon CloudWatch for monitoring and Amazon S3 for content storage.","AWS IAM for access control and AWS PrivateLink for network isolation.","Amazon Bedrock Guardrails with custom word filters and PII redaction.","A custom Python script for word filtering and Amazon Comprehend for PII detection."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a comprehensive and managed solution for both custom word filtering and PII redaction. Amazon Bedrock Guardrails allows you to define custom word filters to block specific inappropriate words or phrases and includes PII redaction capabilities to automatically detect and remove sensitive information from prompts and responses. Option A (incorrect) focuses on monitoring and storage, which do not provide real-time content filtering or PII redaction. Option B (incorrect) addresses access control and network security, which are important but unrelated to content moderation or PII handling within the generative AI workflow. Option D (incorrect) involves custom development (Python script) and a separate service (Amazon Comprehend) for PII, increasing operational overhead and complexity compared to the integrated capabilities of Bedrock Guardrails.', 66, 'm_66_1', 13, NULL, NULL);

