-- Module: m_66_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A non-profit organization is developing an Amazon Bedrock application to assist with grant writing. They are concerned about potential biases in the generated text that could inadvertently favor certain demographics or exclude others. The organization needs a strategy to identify and mitigate such biases to ensure fairness in their outputs. Which approach is most aligned with responsible AI principles?', '["Rely on the foundational model''s default settings, assuming it is pre-trained to be unbiased.","Implement a post-processing AWS Lambda function to manually review and edit generated content for bias.","Monitor Amazon CloudWatch metrics for model invocation rates and latency to ensure consistent performance.","Establish a feedback loop for human review of outputs, evaluate for fairness, and refine Bedrock Guardrails or prompt engineering."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most comprehensive and responsible approach to address bias and fairness in generative AI outputs. It involves actively evaluating outputs for bias through human review, which is crucial for subjective areas like fairness, and then using that feedback to refine the system. This can involve adjusting Bedrock Guardrails (e.g., for content policies) or improving prompt engineering to guide the model towards more equitable responses. Option A (incorrect) is a dangerous assumption; foundational models can reflect biases present in their training data. Option B (incorrect) involves manual review and editing, which is reactive, highly inefficient, and does not scale or provide a systematic way to mitigate bias at the source. Option C (incorrect) focuses on operational performance metrics, which are unrelated to detecting or mitigating bias in content.', 66, 'm_66_4', 14, NULL, NULL),
  ('mock_64_all_1775003892874', 'A global manufacturing company uses Amazon Bedrock to assist engineers with design specifications. The company has strict internal policies and industry regulations that dictate acceptable terminology, safety standards, and design constraints. The generative AI outputs must consistently adhere to these policies. Which Bedrock feature should be used to enforce policy-compliant outputs?', '["Fine-tune the foundational model with a dataset of compliant design specifications.","Implement a custom post-processing AWS Lambda function to validate outputs against policy rules.","Configure Amazon Bedrock Guardrails with custom word filters, topic denial, and content filters reflecting policies.","Use Amazon CloudWatch to monitor generated output for policy violations after deployment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective and managed approach for enforcing policy-compliant outputs. Amazon Bedrock Guardrails allows the configuration of various controls, including custom word filters (for terminology), topic denial (for irrelevant content), and content filters (for safety standards and general compliance), which can be tailored to reflect the company''s internal policies and industry regulations. Option A (incorrect) involves fine-tuning, which can guide the model''s style and knowledge but is not a direct, configurable enforcement mechanism for specific policy rules. Option B (incorrect) requires significant custom development and maintenance of an AWS Lambda function, increasing operational overhead compared to a managed Guardrails solution. Option D (incorrect) is a reactive monitoring approach that identifies violations after they occur, rather than preventing them proactively.', 66, 'm_66_4', 15, NULL, NULL),
  ('mock_64_all_1775003892874', 'A social media analytics firm uses Amazon Bedrock to summarize public sentiment from large datasets. They are concerned that the model''s interpretations might drift over time, leading to biased or inaccurate sentiment analysis. The firm needs a way to continuously monitor the model''s output quality and detect any significant changes or biases. Which AWS service can help monitor Bedrock''s generative AI outputs for drift or bias?', '["AWS IAM for auditing model access patterns and preventing unauthorized changes.","Amazon S3 for storing all model outputs and periodically reviewing them manually.","Amazon CloudWatch for collecting and analyzing custom metrics on Bedrock outputs, potentially with human-in-the-loop review.","AWS PrivateLink to ensure secure and private access to Bedrock, preventing external interference."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate service for monitoring generative AI outputs for drift or bias. Amazon CloudWatch can be used to collect custom metrics derived from Bedrock outputs (e.g., sentiment scores, specific keyword frequencies, or even human-in-the-loop annotations), allowing the firm to track trends, detect anomalies, and identify potential drift or bias over time. Option A (incorrect) focuses on access control, which is important for security but does not monitor the quality or bias of the model''s outputs. Option B (incorrect) involves manual review, which is not scalable or continuous for large datasets. Option D (incorrect) ensures secure network connectivity but does not provide capabilities for monitoring model output quality or bias.', 66, 'm_66_4', 16, NULL, NULL),
  ('mock_64_all_1775003892874', 'A customer support center is deploying an Amazon Bedrock-powered chatbot. To ensure responsible AI practices, they require that the chatbot''s responses are consistently helpful, safe, and factually accurate based on their knowledge base. Additionally, all interactions must be logged for audit, and access to the models must be strictly controlled. Which combination of Bedrock features and AWS services best supports these comprehensive requirements?', '["AWS PrivateLink for secure access, Amazon CloudWatch for monitoring, and Amazon S3 for storage.","AWS IAM for access control, Amazon Bedrock Guardrails for safety and grounding, and Amazon Bedrock Model Invocation Logging for audit.","Custom AWS Lambda functions for content filtering, Amazon Comprehend for PII detection, and Amazon CloudTrail for API logging.","Fine-tuning foundational models for accuracy, client-side input validation, and manual review of all chatbot responses."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most comprehensive and managed solution for the stated requirements. AWS IAM ensures strict access control to foundational models. Amazon Bedrock Guardrails enforces safety, content policies, and can be configured with grounding to a knowledge base for factual accuracy. Amazon Bedrock Model Invocation Logging provides detailed audit trails of all interactions. This combination directly addresses all key aspects of responsible AI, safety, accuracy, and governance. Option A (incorrect) focuses on network security, monitoring, and storage, which are important infrastructure aspects but do not directly provide content safety, factual accuracy, or detailed invocation logging. Option C (incorrect) involves custom development with AWS Lambda and Amazon Comprehend, increasing operational overhead, and CloudTrail only logs API calls, not full prompt/response payloads. Option D (incorrect) relies on fine-tuning, client-side controls, and manual review, which are less scalable, less robust, and more operationally intensive than managed Bedrock features.', 66, 'm_66_4', 17, NULL, NULL);

