INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775003892874', 'A company is developing a Retrieval Augmented Generation (RAG) application for customer support. They need to continuously evaluate the relevance and factual accuracy of the generated responses against retrieved documents, aiming for the MOST efficient automated evaluation process. Which approach should they implement?', '["Implement an LLM-as-a-judge system using Amazon Bedrock to score responses based on relevance to retrieved context and factual consistency, integrated with an automated pipeline.","Manually review a sample of generated responses daily and provide feedback through a custom web interface hosted on Amazon EC2, then aggregate scores in Amazon DynamoDB.","Develop a rule-based system using AWS Lambda to check for keyword presence from retrieved documents in the generated response, storing results in Amazon S3.","Use Amazon SageMaker Ground Truth to create a human labeling workflow for every single generated response, then train a classification model to predict human scores."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) leverages the LLM-as-a-judge paradigm, which is a highly efficient and scalable method for automated evaluation of GenAI outputs. By using Amazon Bedrock, developers can prompt a powerful foundational model to act as a judge, scoring responses for relevance and factual consistency against the retrieved context, significantly reducing manual effort and integrating seamlessly into automated pipelines. Option B (incorrect) involves significant manual effort and operational overhead with EC2 and DynamoDB for daily reviews, which contradicts the ''MOST efficient automated evaluation'' constraint. Option C (incorrect) is a rule-based system that is often brittle and lacks the nuanced understanding required for complex relevance and factual accuracy assessments, leading to lower quality evaluations compared to an LLM-as-a-judge. Option D (incorrect) suggests using Amazon SageMaker Ground Truth for every single response, which would be extremely costly and operationally intensive for continuous evaluation, and training a classification model might not capture the full complexity of human judgment as effectively as an LLM-as-a-judge.', 68, 'm_68_1', 1, NULL, NULL),
  ('mock_64_all_1775003892874', 'A financial institution is deploying a GenAI application for market analysis, requiring high accuracy and explainability. They need to establish automated quality gates to prevent models from deploying if they exhibit hallucinations or factual inconsistencies, with a focus on real-time validation during inference. Which strategy should they adopt?', '["Perform periodic batch evaluations of model outputs against a golden dataset using Amazon SageMaker Batch Transform, and manually review results.","Integrate human-in-the-loop review using Amazon Augmented AI (A2I) for all inference requests, blocking deployment if human review rates fall below a threshold.","Deploy the GenAI model behind an Amazon SageMaker Endpoint with a custom inference pre-processor and post-processor, using an LLM-as-a-judge or factual consistency metrics to validate outputs in real-time before returning them to the application.","Use Amazon CloudWatch Alarms to monitor the number of errors reported by the application and automatically roll back deployments if the error rate exceeds a predefined threshold."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a robust solution for real-time validation during inference. By using custom pre- and post-processors on an Amazon SageMaker Endpoint, the system can intercept model outputs and apply automated checks (e.g., LLM-as-a-judge, factual consistency metrics) to identify hallucinations or inconsistencies before the response reaches the end-user. This acts as a real-time quality gate. Option A (incorrect) involves periodic batch evaluations and manual review, which does not provide real-time validation during inference and would allow problematic models to be deployed for a period. Option B (incorrect) suggests human-in-the-loop for *all* inference requests, which would introduce significant latency and cost, making it impractical for most real-time applications, and doesn''t directly prevent deployment but rather filters outputs post-deployment. Option D (incorrect) monitors application errors, which is a reactive measure and does not directly validate the quality of the GenAI model''s output for factual consistency or hallucinations at the inference layer.', 68, 'm_68_1', 2, NULL, NULL),
  ('mock_64_all_1775003892874', 'A healthcare provider is building an internal knowledge base chatbot using RAG. They need to evaluate the retrieval component''s effectiveness, specifically ensuring that relevant documents are consistently retrieved for given user queries, and identify cases of low recall. Which evaluation method should they prioritize?', '["Create a ''golden dataset'' of queries with manually annotated relevant document IDs, then automate the calculation of retrieval metrics like Recall@k and Mean Reciprocal Rank (MRR) using AWS Lambda.","Implement an LLM-as-a-judge system to rate the final generated answers for relevance, assuming good answers imply good retrieval.","Rely solely on human feedback from chatbot users, asking them to rate the overall helpfulness of the response, and then infer retrieval quality.","Monitor the latency of the retrieval component using Amazon CloudWatch, assuming faster retrieval indicates better effectiveness."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the need to evaluate the retrieval component''s effectiveness. By creating a golden dataset with known relevant document IDs for specific queries, the team can accurately calculate metrics like Recall@k and MRR. Automating this calculation with AWS Lambda provides an efficient and scalable way to continuously assess if relevant documents are consistently retrieved and identify low recall. Option B (incorrect) evaluates the final generated answer, which is influenced by both retrieval and generation quality. While a good final answer is desired, it doesn''t isolate and directly measure the retrieval component''s performance or identify low recall specifically. Option C (incorrect) relies on subjective overall helpfulness, which is an indirect and often noisy signal for specific retrieval quality issues, and does not provide granular insights into low recall. Option D (incorrect) monitors latency, which is a performance metric, not an effectiveness metric. Faster retrieval does not guarantee higher relevance or better recall.', 68, 'm_68_1', 3, NULL, NULL),
  ('mock_64_all_1775003892874', 'A legal tech company uses GenAI to draft legal documents. They need to implement a system for human experts to review and provide feedback on the generated drafts, capturing specific annotations for accuracy and legal compliance, and integrating this feedback for model improvement. Which AWS service is best suited for this task?', '["Use Amazon Textract to extract text from the generated documents and store it in Amazon S3 for manual review by legal experts.","Develop a custom web application hosted on Amazon EC2 with a database on Amazon RDS for legal experts to input their feedback and annotations.","Implement Amazon SageMaker Ground Truth to create a custom annotation workflow where legal experts can highlight specific sections, add comments, and rate accuracy and compliance, with output integrated for model retraining.","Send generated documents to legal experts via email and ask them to reply with their feedback, then manually parse the emails to extract annotations."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate solution. Amazon SageMaker Ground Truth is designed for building high-quality training datasets and collecting human feedback. It allows for creating custom annotation workflows, enabling legal experts to highlight specific text, add detailed comments, and provide structured ratings for accuracy and compliance. This structured feedback can then be directly used for model improvement and retraining. Option A (incorrect) uses Amazon Textract for text extraction, which is useful for processing existing documents but doesn''t provide a mechanism for human experts to provide structured feedback and annotations on generated content. Option B (incorrect) requires significant development effort and operational overhead to build and maintain a custom web application and database, which is less efficient than leveraging a managed service like Ground Truth. Option D (incorrect) is a highly inefficient, unstructured, and error-prone manual process for collecting feedback, making it unsuitable for systematic model improvement.', 68, 'm_68_1', 4, NULL, NULL),
  ('mock_64_all_1775003892874', 'A research institution is comparing several open-source foundational models for a scientific text generation task. They need a scalable way to run batch inferences with different models and collect metrics on perplexity and ROUGE scores to identify the best performing model. Which AWS services should they use?', '["Use Amazon SageMaker Batch Transform to run inference jobs on large datasets with different models, storing outputs and metrics in Amazon S3 for analysis.","Deploy each model on a dedicated Amazon EC2 instance, manually manage the inference process, and calculate metrics using custom scripts on the instances.","Create an AWS Lambda function for each model to handle inference requests, and use Amazon DynamoDB to store the generated text and metrics.","Utilize Amazon Rekognition to analyze the generated text for content, and Amazon Comprehend to assess sentiment, then manually combine these results."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most scalable and efficient solution for running batch inferences and collecting metrics. Amazon SageMaker Batch Transform is specifically designed for high-throughput, offline inference on large datasets, allowing different models to be run and their outputs and calculated metrics (like perplexity and ROUGE scores) to be stored directly in Amazon S3 for easy analysis. Option B (incorrect) involves significant operational overhead for managing EC2 instances, scaling, and custom script execution, which is not a scalable or efficient approach for comparing multiple models. Option C (incorrect) uses AWS Lambda for inference, which is suitable for real-time, low-latency requests but not optimized for large-scale batch inference, and DynamoDB is not ideal for storing large text outputs and complex metrics. Option D (incorrect) suggests Amazon Rekognition (for image/video analysis) and Amazon Comprehend (for general text analysis, not specific scientific text generation metrics like perplexity or ROUGE), which are entirely inappropriate services for this task.', 68, 'm_68_1', 5, NULL, NULL),
  ('mock_64_all_1775003892874', 'A development team is troubleshooting a RAG application that occasionally generates irrelevant responses. They suspect issues with the retrieval component providing incorrect context. They need a systematic approach to analyze the retrieved documents for specific queries and identify discrepancies. Which solution is most effective?', '["Implement an AWS Lambda function to log the final generated response to Amazon CloudWatch Logs and manually inspect for irrelevance.","Use AWS X-Ray to trace the latency of the retrieval component, assuming high latency correlates with irrelevant documents.","Capture the user query, the top-k retrieved document IDs, and their content in Amazon S3, then use an AWS Lambda function to automate a relevance score comparison against a ''golden dataset'' or an LLM-as-a-judge.","Increase the number of retrieved documents (k) to a very high value to ensure all possible relevant documents are included, then rely on the LLM to filter."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a systematic and effective approach to analyze retrieval issues. By capturing the user query, retrieved document IDs, and their content in Amazon S3, the team creates a dataset for detailed analysis. An AWS Lambda function can then automate the evaluation of these retrieved documents for relevance against a ''golden dataset'' (pre-labeled relevant documents) or by using an LLM-as-a-judge, directly identifying discrepancies and low relevance in the retrieval component. Option A (incorrect) only logs the final response, which doesn''t provide insight into the intermediate retrieval step or allow for direct analysis of the retrieved documents. Option B (incorrect) traces latency, which is a performance metric, not a quality metric for relevance. High latency does not necessarily mean irrelevant documents. Option D (incorrect) increasing ''k'' indiscriminately can introduce more irrelevant context, potentially worsening the problem of ''context overflow'' or making the LLM''s job harder, rather than systematically identifying retrieval discrepancies.', 68, 'm_68_1', 6, NULL, NULL),
  ('mock_64_all_1775003892874', 'A financial application uses a GenAI model for sentiment analysis of news articles. Over time, the model''s performance has degraded, and the team suspects ''embedding drift'' due to changes in market terminology. They need a method to detect changes in the input data''s embedding space. Which AWS service can help automate this detection?', '["Configure Amazon SageMaker Model Monitor to detect data drift on the input features (embeddings) of the deployed model, alerting when significant changes occur.","Manually re-train the model weekly and compare its performance metrics to a baseline, assuming performance degradation indicates embedding drift.","Use Amazon CloudWatch Alarms to monitor the CPU utilization of the inference endpoint, assuming high CPU indicates data drift.","Store all incoming news articles in Amazon S3 and periodically run a custom script on an Amazon EC2 instance to visualize embedding distributions."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective and automated solution. Amazon SageMaker Model Monitor is specifically designed to detect data drift (including embedding drift) and model quality drift in deployed machine learning models. It can analyze the input features (in this case, the embeddings generated from news articles) and automatically alert when their statistical properties significantly change from a baseline, directly addressing the need to detect embedding drift. Option B (incorrect) is a reactive and manual approach. While performance degradation can indicate drift, retraining weekly is resource-intensive and doesn''t provide proactive detection or specific insight into the nature of the drift. Option C (incorrect) monitors CPU utilization, which is an infrastructure metric and has no direct correlation with embedding drift. Option D (incorrect) involves manual scripting and EC2 management, which is less automated and scalable than SageMaker Model Monitor for continuous detection.', 68, 'm_68_1', 7, NULL, NULL),
  ('mock_64_all_1775003892874', 'A customer support chatbot built with GenAI is occasionally providing incomplete or cut-off responses, indicating potential ''context overflow'' issues. The team needs to analyze the length of input prompts and retrieved context to identify when the model''s token limit is being exceeded. Which AWS services should they use for this analysis?', '["Use Amazon CloudWatch Metrics to monitor the overall token count of the model''s output and trigger an alarm when it''s below a threshold.","Store all chatbot interactions, including prompt and retrieved context, in Amazon DynamoDB and manually query for length anomalies.","Instrument the application to log the token count of both the input prompt and the retrieved context to Amazon CloudWatch Logs, then use CloudWatch Logs Insights to query and identify instances exceeding the model''s token limit.","Deploy a custom Amazon EC2 instance to run a script that periodically samples interactions and calculates token lengths, storing results in Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides an efficient and scalable solution. By instrumenting the application to log the token count of both the input prompt and the retrieved context to Amazon CloudWatch Logs, the team can capture the necessary data. CloudWatch Logs Insights then allows for powerful querying and analysis of these logs to identify specific instances where the combined token count exceeds the model''s limit, directly pinpointing context overflow issues. Option A (incorrect) monitors only the output token count, which is insufficient to diagnose context overflow caused by input or retrieved context length. Option B (incorrect) uses Amazon DynamoDB, which is not ideal for storing large volumes of detailed log data for complex queries, and manual querying is inefficient. Option D (incorrect) involves managing an EC2 instance and custom scripting, which adds operational overhead and is less efficient than leveraging managed logging and analytics services.', 68, 'm_68_1', 8, NULL, NULL),
  ('mock_64_all_1775003892874', 'A real-time GenAI application for code generation is experiencing slow response times and occasional timeouts. The team needs to identify bottlenecks in the inference pipeline, including model loading, processing, and external API calls, to optimize performance. Which AWS service is best for diagnosing these issues?', '["AWS X-Ray, to trace requests end-to-end across all components of the inference pipeline, including calls to Amazon Bedrock or custom models, and external services.","Amazon CloudWatch Logs, to aggregate all application logs and manually search for latency metrics and error messages.","Amazon SageMaker Model Monitor, to detect data drift in the input prompts, assuming drift causes slow response times.","Amazon CloudWatch Metrics, to monitor CPU and memory utilization of the inference endpoint, and set alarms for high usage."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective service for diagnosing performance bottlenecks across a distributed inference pipeline. AWS X-Ray provides end-to-end tracing, allowing developers to visualize the entire request flow, identify which components (e.g., model loading, processing, external API calls) are contributing most to latency, and pinpoint specific bottlenecks. Option B (incorrect) relies on manual log searching, which is inefficient and difficult for correlating events across multiple services for a single request to identify bottlenecks. Option C (incorrect) uses Amazon SageMaker Model Monitor for data drift detection, which is unrelated to identifying performance bottlenecks in the inference pipeline. Option D (incorrect) monitors infrastructure metrics like CPU/memory, which can indicate a bottleneck but doesn''t provide the granular, end-to-end trace of a request''s journey through the pipeline that X-Ray offers.', 68, 'm_68_1', 9, NULL, NULL),
  ('mock_64_all_1775003892874', 'A streaming GenAI service, which provides real-time content summarization, is occasionally failing to deliver complete summaries. The team needs to monitor the streaming output for truncation or errors and automatically alert when such issues occur. Which AWS services should they combine for this monitoring solution?', '["Use Amazon Kinesis Data Streams to capture the streaming output, and Amazon CloudWatch Logs to store the raw data for manual inspection.","Implement an AWS Lambda function to process the streaming output from Amazon Kinesis Data Streams, check for expected summary length or error patterns, and publish custom metrics to Amazon CloudWatch Metrics, triggering Amazon CloudWatch Alarms.","Deploy Amazon EC2 instances to host a custom monitoring application that continuously reads the streaming output and sends notifications via Amazon SNS.","Configure Amazon S3 to store the streaming output as files, and then use Amazon Athena to periodically query for incomplete summaries."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a robust and automated monitoring solution for streaming GenAI outputs. An AWS Lambda function can process the real-time output from Amazon Kinesis Data Streams, performing checks for truncation (e.g., minimum length) or specific error patterns. It can then publish custom metrics to Amazon CloudWatch Metrics, which can trigger Amazon CloudWatch Alarms when thresholds are breached, ensuring automatic alerts. Option A (incorrect) uses Kinesis Data Streams and CloudWatch Logs, but relies on manual inspection of logs, which is not an automated alerting solution. Option C (incorrect) involves managing EC2 instances and custom application development, which introduces significant operational overhead compared to a serverless and managed solution. Option D (incorrect) stores output in S3 and uses Athena for periodic querying, which is a batch-oriented approach and not suitable for real-time monitoring and immediate alerting of streaming issues.', 68, 'm_68_1', 10, NULL, NULL);

