INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A large e-commerce company plans to integrate a generative AI chatbot into its customer service portal to answer common queries. The solution must be highly scalable, cost-effective, and require the LEAST operational overhead for infrastructure management. The company prefers using managed services where possible.', '["Deploy an Amazon EC2 instance with a self-managed LLM, fronted by an Application Load Balancer and Auto Scaling Group.","Utilize Amazon Bedrock with a pre-trained foundation model, exposed via Amazon API Gateway, and orchestrated by AWS Lambda.","Host a custom fine-tuned model on Amazon SageMaker endpoints, integrated with a custom web application running on Amazon ECS.","Implement a solution using AWS Step Functions to orchestrate calls to a third-party LLM API, with custom caching on Amazon ElastiCache."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon Bedrock, a fully managed service for foundation models, which significantly reduces operational overhead. Combining it with Amazon API Gateway and AWS Lambda creates a serverless architecture that is highly scalable, cost-effective, and requires minimal infrastructure management, aligning perfectly with the ''LEAST operational overhead'' constraint. Option A (incorrect) involves managing EC2 instances, an Application Load Balancer, and Auto Scaling Group, which introduces significant operational overhead compared to a serverless approach. Option C (incorrect) requires managing SageMaker endpoints and an Amazon ECS cluster, both of which involve more operational management than a purely serverless Bedrock/Lambda/API Gateway solution. Option D (incorrect) introduces a dependency on a third-party LLM and custom caching with Amazon ElastiCache, increasing complexity and operational overhead, especially for a core GenAI solution.', 64, 'm_64_1', 1, NULL, NULL),
  ('mock_64_all_1775005739332', 'A media company wants to build a content generation platform using generative AI. They need to design a solution that allows rapid experimentation with different foundation models and providers, supports quick iteration, and ensures the architecture is resilient to individual model failures. Which architectural pattern should they prioritize for MOST flexibility and resilience?', '["Hardcode specific Amazon Bedrock model IDs directly into the application logic for each content type.","Implement a centralized model abstraction layer using AWS Lambda that dynamically routes requests to different Amazon Bedrock models or external APIs based on configuration.","Deploy multiple custom fine-tuned models on separate Amazon SageMaker endpoints, with manual failover mechanisms.","Utilize a single large, general-purpose foundation model and fine-tune it extensively for all content generation tasks."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes a model abstraction layer, which is a key pattern for flexibility and resilience. By using AWS Lambda to dynamically route requests, the application can easily switch between different Amazon Bedrock models or even external APIs without code changes, enabling rapid experimentation and providing resilience against individual model failures. Option A (incorrect) introduces tight coupling, making it difficult to switch models or providers, and reduces resilience. Option C (incorrect) involves manual failover and managing multiple SageMaker endpoints, which increases operational overhead and complexity compared to a managed abstraction layer. Option D (incorrect) limits flexibility to a single model and extensive fine-tuning can be time-consuming and expensive, making rapid experimentation with diverse models challenging.', 64, 'm_64_1', 2, NULL, NULL),
  ('mock_64_all_1775005739332', 'A financial services firm is developing a generative AI application to summarize complex financial reports. The solution requires strict data privacy and compliance, ensuring that sensitive data used for summarization never leaves the AWS environment. The firm also aims for a cost-effective solution with minimal data transfer costs. Which design approach is MOST suitable?', '["Send financial reports to a third-party GenAI API hosted outside AWS for processing.","Use Amazon Bedrock with VPC Endpoints to process financial reports, ensuring all traffic remains within the AWS network.","Deploy a custom large language model on Amazon EC2 instances within a private subnet, managing all infrastructure.","Process reports on-premises and only send anonymized summaries to a public Amazon Bedrock endpoint."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) uses Amazon Bedrock with VPC Endpoints, which allows private connectivity between your VPC and Bedrock, ensuring that sensitive data remains within the AWS network and does not traverse the public internet. This satisfies the strict data privacy and compliance requirements while leveraging a managed service for cost-effectiveness and reduced operational overhead. Option A (incorrect) violates data privacy and compliance requirements by sending sensitive data outside AWS. Option C (incorrect) involves significant operational overhead for managing a custom LLM on EC2 instances, which is not cost-effective or efficient for a summarization task when managed services are available. Option D (incorrect) introduces complexity with on-premises processing and might still incur data transfer costs for summaries, and it doesn''t fully leverage AWS capabilities for secure processing.', 64, 'm_64_1', 3, NULL, NULL),
  ('mock_64_all_1775005739332', 'A healthcare provider is building a GenAI application to assist doctors with medical research by generating summaries from a vast internal knowledge base. The architecture needs to be highly available, scalable, and provide low-latency responses, while adhering to HIPAA compliance. They want to minimize the effort in managing underlying infrastructure. Which design pattern BEST meets these requirements?', '["A monolithic application on a single Amazon EC2 instance that hosts both the knowledge base and the GenAI model.","A serverless architecture using Amazon API Gateway, AWS Lambda, and Amazon Bedrock, with the knowledge base stored in Amazon S3 and indexed by a Bedrock Knowledge Base.","A containerized application deployed on Amazon ECS with Fargate, connecting to a self-managed vector database on Amazon EC2 and a custom-deployed LLM.","An on-premises data center hosting the knowledge base and a locally deployed open-source LLM, accessed via a VPN connection to AWS for external services."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) leverages a fully serverless architecture with Amazon API Gateway, AWS Lambda, and Amazon Bedrock. This combination provides high availability, scalability, and low-latency responses with minimal infrastructure management. Storing the knowledge base in Amazon S3 and indexing it with a Bedrock Knowledge Base ensures efficient retrieval and compliance. Option A (incorrect) represents a single point of failure and lacks scalability, making it unsuitable for a highly available and scalable application. Option C (incorrect) involves managing an ECS cluster, a self-managed vector database on EC2, and a custom LLM, which significantly increases operational overhead compared to a serverless approach. Option D (incorrect) introduces latency and compliance challenges with on-premises infrastructure and VPN connections, and does not leverage the scalability and managed services of AWS effectively.', 64, 'm_64_1', 4, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_64_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A research institution needs to build a Retrieval Augmented Generation (RAG) system for scientific papers. The system must store millions of high-dimensional embeddings and support low-latency semantic search queries from a large user base. Updates to the document corpus and their embeddings occur frequently. Which vector store solution is MOST suitable for this scenario, balancing performance and operational overhead?', '["Amazon S3 to store raw embeddings as files, with custom indexing logic on Amazon EC2.","Amazon DynamoDB to store embeddings as binary attributes, with a global secondary index for metadata.","Amazon OpenSearch Service with the k-NN plugin (or vector engine) to store and search embeddings, integrated with a data ingestion pipeline.","Amazon Aurora PostgreSQL with the pgvector extension, deployed on a single instance with manual scaling."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon OpenSearch Service with its k-NN plugin or vector engine, which is specifically designed for high-performance, low-latency vector search over large datasets. It provides managed scalability and features like indexing and search capabilities that are ideal for RAG systems, balancing performance with reduced operational overhead. Option A (incorrect) would require significant custom development for indexing and search, leading to high operational overhead and potentially poor performance for low-latency queries. Option B (incorrect) is not designed for efficient high-dimensional vector search and would be inefficient and costly for this use case. Option D (incorrect) offers vector search capabilities with pgvector, but a single instance with manual scaling might not meet the ''low-latency semantic search queries from a large user base'' and ''frequent updates'' requirements as effectively as a managed, scalable service like OpenSearch Service.', 64, 'm_64_4', 5, NULL, NULL),
  ('mock_64_all_1775005739332', 'A startup is developing a GenAI-powered legal assistant that needs to retrieve relevant clauses from a vast database of legal documents. The solution requires storing document embeddings and associated metadata (e.g., document type, date, jurisdiction) to enable filtered searches. The primary goal is to ensure efficient retrieval based on both semantic similarity and metadata filtering. Which vector store strategy is MOST effective?', '["Store embeddings in Amazon S3 and metadata in a separate Amazon RDS database, performing two separate lookups.","Use Amazon DynamoDB to store embeddings and metadata in the same table, relying on DynamoDB''s query capabilities for filtering.","Implement Amazon Aurora PostgreSQL with the pgvector extension, storing embeddings and metadata in the same table for combined semantic and metadata filtering.","Utilize Amazon Bedrock Knowledge Bases, which inherently support storing embeddings and metadata for efficient RAG retrieval."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) utilizes Amazon Bedrock Knowledge Bases, which are specifically designed for RAG workflows and inherently support storing embeddings alongside rich metadata. This allows for efficient retrieval based on both semantic similarity and metadata filtering within a single, managed service, simplifying the architecture and reducing operational overhead. Option A (incorrect) would introduce latency and complexity by requiring two separate lookups and custom logic to combine results. Option B (incorrect) is not optimized for high-dimensional vector search and would be inefficient for semantic similarity queries, even if it can store metadata. Option C (incorrect) is a viable option for combined semantic and metadata filtering, but Amazon Bedrock Knowledge Bases are a more purpose-built, fully managed solution for RAG, often requiring less setup and management for this specific use case.', 64, 'm_64_4', 6, NULL, NULL),
  ('mock_64_all_1775005739332', 'A content platform needs to update its RAG system with new articles daily. The vector store, currently Amazon OpenSearch Service, must reflect these updates with minimal delay to ensure users always get the latest information. The solution should be automated and scalable. Which approach ensures the MOST efficient and timely synchronization of new data into the vector store?', '["Manually upload new article embeddings to OpenSearch Service once a week.","Develop a cron job on an Amazon EC2 instance to periodically re-index the entire OpenSearch Service domain.","Set up an AWS Lambda function triggered by new article uploads to Amazon S3, which generates embeddings and indexes them into OpenSearch Service.","Use AWS DataSync to transfer new articles from an on-premises file share to OpenSearch Service daily."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most efficient and timely synchronization. An AWS Lambda function triggered by new content in Amazon S3 can immediately process the new articles, generate embeddings, and index them into Amazon OpenSearch Service. This creates an automated, event-driven pipeline that ensures the vector store is updated with minimal delay and scales automatically. Option A (incorrect) is a manual process and does not meet the ''minimal delay'' requirement for daily updates. Option B (incorrect) involves re-indexing the entire domain, which is inefficient and resource-intensive for frequent updates, especially with a growing dataset. Option D (incorrect) is designed for large-scale data transfer between storage services or on-premises to AWS, not for real-time, event-driven indexing into a vector search engine.', 64, 'm_64_4', 7, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is building a RAG system for internal documentation, which includes various file types like PDFs, Word documents, and Markdown files. They need to store embeddings and metadata for these documents in a scalable and cost-effective manner. The system requires support for complex queries that combine semantic search with filtering based on document attributes (e.g., author, department, creation date). Which vector store solution is the MOST appropriate for this hybrid search requirement?', '["Store embeddings in Amazon S3 and metadata in Amazon DynamoDB, then combine results programmatically.","Utilize Amazon Aurora PostgreSQL with the pgvector extension, storing both embeddings and metadata in a single table.","Use Amazon OpenSearch Service with the k-NN plugin for vector search and its native indexing capabilities for metadata.","Implement a custom solution on Amazon EC2 instances with a self-managed vector database and a separate relational database for metadata."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most appropriate solution. Amazon OpenSearch Service, with its k-NN plugin or vector engine, is excellent for high-performance vector search. Its native indexing capabilities also allow for storing and querying rich metadata alongside the vector embeddings. This enables efficient hybrid search (semantic + metadata filtering) within a single, scalable, and managed service. Option A (incorrect) would introduce complexity and potential latency by requiring separate storage and programmatic joining of results. Option B (incorrect) is a strong contender, but OpenSearch Service is often preferred for its specialized search capabilities and scalability for large, frequently updated document corpuses, especially when complex text search features are also desired. Option D (incorrect) would incur significant operational overhead and management complexity due to self-managed databases and EC2 instances, failing the ''cost-effective'' and ''scalable'' implicit requirements of a professional-level solution.', 64, 'm_64_4', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_64_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A legal tech company is developing a RAG system to answer complex legal questions by retrieving information from a vast corpus of legal precedents. To ensure high accuracy, the system needs to identify the most relevant document chunks, even if the initial vector search returns a broad set of candidates. Which retrieval mechanism should be implemented to improve the precision of the retrieved results?', '["Rely solely on keyword search to retrieve documents based on exact term matches.","Implement a basic vector search using a general-purpose embedding model without any post-processing.","Utilize a semantic search approach combined with a reranking model (e.g., Amazon Bedrock Rerankers) to re-order the initial search results.","Increase the chunk size of the legal documents to include more context in each retrieved piece."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective approach to improve precision. Semantic search with a reranking model, such as Amazon Bedrock Rerankers, allows the system to first retrieve a broader set of semantically similar documents and then use a more sophisticated model to re-score and re-order these results, pushing the most relevant chunks to the top. This significantly improves the precision of the retrieved information. Option A (incorrect) is prone to missing relevant documents due to synonymy or different phrasing and is not suitable for complex semantic understanding. Option B (incorrect) might return many semantically similar but not highly relevant results without further refinement, leading to lower precision. Option D (incorrect) can lead to less precise retrieval by including too much irrelevant context in each chunk, making it harder for the LLM to focus on the most pertinent information.', 64, 'm_64_5', 9, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is building a GenAI application that needs to answer user questions by retrieving information from a large, diverse set of internal documents. Users often ask multi-part or ambiguous questions. To ensure comprehensive and accurate answers, the system needs to break down complex queries into simpler, more specific sub-queries before performing retrieval. Which advanced retrieval mechanism is BEST suited for this requirement?', '["Implement a simple vector search directly on the original user query.","Use a keyword search mechanism with basic stemming and lemmatization.","Employ query decomposition or query expansion techniques using an LLM to generate multiple sub-queries or reformulations.","Increase the number of retrieved document chunks from the vector store to provide more context."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes query decomposition or query expansion, which are advanced retrieval mechanisms specifically designed to handle complex or ambiguous user questions. By using an LLM to break down a multi-part query into simpler sub-queries or to generate multiple reformulations, the system can perform more targeted and effective retrievals, leading to more comprehensive and accurate answers. Option A (incorrect) would likely result in suboptimal retrieval for complex queries, as the single vector might not capture all nuances. Option B (incorrect) is a basic lexical search technique and is insufficient for understanding the semantic complexity of multi-part or ambiguous questions. Option D (incorrect) might retrieve more data, but it doesn''t solve the problem of ambiguous queries and could introduce more irrelevant information, increasing the burden on the LLM.', 64, 'm_64_5', 10, NULL, NULL),
  ('mock_64_all_1775005739332', 'A news organization wants to implement a RAG system to summarize breaking news articles. The articles are short, frequently updated, and contain time-sensitive information. The system needs to efficiently chunk these articles for embedding and retrieval, ensuring that each chunk maintains sufficient context while being concise. Which document chunking strategy is MOST appropriate for this scenario?', '["Chunk articles into fixed-size segments of 2000 tokens, regardless of content boundaries.","Chunk articles into sentences, then combine adjacent sentences into chunks of 100-200 tokens, respecting paragraph boundaries.","Treat each entire news article as a single chunk, even if it''s very long.","Split articles into individual words, then embed each word separately."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is a highly effective chunking strategy for news articles. By chunking into sentences and then combining adjacent sentences while respecting paragraph boundaries, it ensures that each chunk is semantically coherent, concise, and maintains sufficient context for accurate retrieval. This approach is particularly suitable for frequently updated, time-sensitive content where precision is key. Option A (incorrect) fixed-size chunking can split sentences or paragraphs in half, destroying semantic coherence and reducing retrieval quality. Option C (incorrect) would result in very large chunks for longer articles, making retrieval less precise and increasing the LLM''s context window burden. Option D (incorrect) would lose all contextual information and make semantic retrieval ineffective.', 64, 'm_64_5', 11, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is building a GenAI application that allows users to query a knowledge base of product manuals. The system needs to provide a consistent and unified interface for retrieval, regardless of the underlying vector store or search mechanisms used. This is crucial for future extensibility and maintainability. Which architectural component should be implemented to achieve this goal?', '["Directly integrate the application with the specific API of the chosen vector database.","Create a custom API Gateway endpoint for each different retrieval mechanism.","Develop a retrieval service layer (e.g., using AWS Lambda or Amazon ECS) that abstracts the underlying search logic and provides a standardized API.","Embed all retrieval logic directly within the frontend application code."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a retrieval service layer, which is a standard architectural pattern for providing a consistent and unified interface. By abstracting the underlying search logic (e.g., vector database, keyword search, reranking) behind a standardized API, the application can interact with this layer without needing to know the specific implementation details. This significantly improves extensibility, maintainability, and allows for easy swapping of retrieval mechanisms in the future. Option A (incorrect) creates tight coupling, making it difficult to change or add new retrieval mechanisms. Option B (incorrect) would lead to a proliferation of endpoints and increased management complexity, defeating the purpose of a unified interface. Option D (incorrect) embeds business logic in the client, making it difficult to update, test, and maintain, and is not scalable or secure.', 64, 'm_64_5', 12, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_64_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A manufacturing company needs to process unstructured text data from incident reports, including identifying key entities like machine names, fault codes, and affected components, before feeding it to a generative AI model for root cause analysis. The solution must be highly automated and require LEAST custom code. Which AWS service combination should be used for this data processing pipeline?', '["Use Amazon EC2 instances with custom Python scripts for entity extraction.","Store reports in Amazon S3, use AWS Lambda to trigger Amazon Comprehend for custom entity recognition, and then store structured output in Amazon DynamoDB.","Manually review and extract entities from each report, then input them into the GenAI model.","Use AWS Glue to extract entities from the reports and store them in a data warehouse."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a highly automated solution with the least custom code. Amazon S3 serves as scalable storage. AWS Lambda can be triggered by new uploads, orchestrating the process. Amazon Comprehend''s custom entity recognition can accurately extract specific entities (machine names, fault codes, etc.) from unstructured text with minimal custom code, especially after training. The structured output can then be stored in Amazon DynamoDB for easy access by the GenAI model. Option A (incorrect) requires significant custom code development and management of EC2 instances, increasing operational overhead. Option C (incorrect) is a manual process, which is not scalable or efficient for large volumes of data. Option D (incorrect) AWS Glue is powerful for ETL, but for specialized entity extraction from unstructured text with minimal custom code, Amazon Comprehend is a more purpose-built and efficient service.', 64, 'm_64_3', 13, NULL, NULL),
  ('mock_64_all_1775005739332', 'A marketing agency receives customer feedback in various formats, including text reviews, images with embedded text, and audio recordings. They need to preprocess this multimodal data into a unified, structured format (JSON) before feeding it to a generative AI model for sentiment analysis and summary generation. Which AWS services should be integrated into a pipeline to achieve this with high accuracy?', '["Use Amazon Rekognition for all data types (text, image, audio) and Amazon SQS for queuing.","Store raw data in Amazon S3, use Amazon Transcribe for audio, Amazon Textract for images, Amazon Comprehend for text, and AWS Lambda for orchestration and JSON formatting.","Manually convert all data into text files and then use a single Amazon SageMaker endpoint for all processing.","Deploy a custom machine learning model on Amazon EC2 to handle all multimodal data processing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a robust and accurate pipeline for multimodal data. Amazon S3 is used for raw data storage. Amazon Transcribe accurately converts audio to text. Amazon Textract extracts text from images and documents. Amazon Comprehend performs advanced text analysis like sentiment detection and entity extraction. AWS Lambda orchestrates these services and formats the output into a unified JSON structure, ensuring high accuracy and scalability. Option A (incorrect) Amazon Rekognition is primarily for image and video analysis, not for general text or audio processing. Option C (incorrect) manual conversion is not scalable or efficient, and a single SageMaker endpoint might not be optimized for all specific multimodal tasks. Option D (incorrect) requires significant custom development and management of EC2 instances, increasing operational overhead and potentially reducing accuracy compared to specialized AWS AI services.', 64, 'm_64_3', 14, NULL, NULL),
  ('mock_64_all_1775005739332', 'A data science team is preparing a large dataset of customer interactions (chat logs, emails) for fine-tuning a generative AI model. They need to ensure the data is free of personally identifiable information (PII) and formatted consistently (e.g., all timestamps in ISO 8601, consistent capitalization) to improve model performance. Which AWS services can be used to implement a data quality and normalization pipeline with LEAST manual intervention?', '["Manually review and edit each interaction log to remove PII and normalize formatting.","Use AWS Glue Data Quality for PII detection and data profiling, and AWS Lambda with custom scripts for normalization and formatting.","Store data in Amazon S3 and use Amazon Macie for PII detection, then apply manual transformations.","Deploy a custom Python script on an Amazon EC2 instance to perform all data cleansing and normalization."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides an automated and efficient solution with least manual intervention. AWS Glue Data Quality can be used to detect PII and profile data quality issues at scale. AWS Lambda, triggered by new data or on a schedule, can then execute custom Python scripts for specific normalization tasks like timestamp formatting and capitalization, ensuring data consistency. This combination leverages managed services for scalability and automation. Option A (incorrect) is a manual process and not scalable or efficient for large datasets. Option C (incorrect) Amazon Macie is excellent for PII detection but doesn''t provide automated transformation capabilities, requiring manual intervention for normalization. Option D (incorrect) requires managing EC2 instances and developing extensive custom scripts, increasing operational overhead compared to leveraging AWS Glue Data Quality.', 64, 'm_64_3', 15, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is ingesting tabular data from various sources to train a generative AI model for data augmentation. Before feeding the data to the model, they need to ensure that numerical columns are within expected ranges, categorical columns have valid values, and missing values are handled appropriately. Which AWS service is specifically designed to define, monitor, and enforce data quality rules in this pipeline?', '["Amazon S3 for data storage and manual inspection.","AWS Lambda with custom Python scripts to validate each data point.","AWS Glue Data Quality to define rules, evaluate data, and generate data quality scores.","Amazon DynamoDB to store data and rely on its schema enforcement for validation."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Glue Data Quality, which is specifically designed for defining, monitoring, and enforcing data quality rules across various data sources. It allows users to create data quality rules (e.g., range checks, valid values, missing value checks) and evaluate data against these rules, generating data quality scores and identifying issues, which is crucial for preparing high-quality data for GenAI models. Option A (incorrect) Amazon S3 is storage, not a data quality service. Manual inspection is not scalable. Option B (incorrect) AWS Lambda can run custom scripts, but AWS Glue Data Quality provides a more comprehensive, managed, and scalable framework for data quality management, reducing the need for extensive custom code. Option D (incorrect) Amazon DynamoDB is a NoSQL database and its schema enforcement is not designed for complex data quality validation rules across diverse datasets.', 64, 'm_64_3', 16, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_64_6
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A software development team is building an internal GenAI assistant to help engineers with coding tasks. They want to ensure that the model''s responses adhere to company coding standards and do not expose sensitive internal project details. The team needs to implement guardrails to prevent unsafe or non-compliant outputs. Which Amazon Bedrock feature should be used for this purpose?', '["Fine-tuning the foundation model with a dataset of compliant code examples.","Implementing a custom post-processing Lambda function to filter model outputs.","Utilizing Amazon Bedrock Guardrails to define policies for content filtering and sensitive information detection.","Relying solely on prompt engineering techniques to guide the model''s behavior."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon Bedrock Guardrails, which is specifically designed to implement safety policies and content filtering for GenAI applications. It allows defining rules to detect and filter out harmful content, PII, or non-compliant outputs, ensuring that the model''s responses adhere to company standards and security requirements. Option A (incorrect) fine-tuning can influence model behavior but is not a direct mechanism for enforcing real-time content policies or preventing specific types of unsafe outputs. Option B (incorrect) a custom post-processing Lambda function can filter outputs, but Bedrock Guardrails offers a managed, configurable, and more comprehensive solution for content moderation. Option D (incorrect) prompt engineering is crucial for guiding model behavior but is not sufficient on its own to enforce strict content policies and prevent all unsafe or non-compliant outputs reliably.', 64, 'm_64_6', 17, NULL, NULL),
  ('mock_64_all_1775005739332', 'A customer support center is deploying a generative AI assistant and needs to maintain a consistent conversation flow across multiple user interactions. The assistant must remember previous turns in the conversation to provide contextually relevant responses. Which strategy is MOST effective for managing conversation state in this GenAI application?', '["Restart the conversation context with each new user query, ignoring previous interactions.","Store the entire conversation history in a client-side cookie and send it with every request.","Implement a session management mechanism, storing conversation history in a persistent data store like Amazon DynamoDB or Amazon ElastiCache, and passing a session ID with each request.","Fine-tune the foundation model to inherently remember past conversations without external state management."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most effective strategy for managing conversation state. By implementing a session management mechanism and storing conversation history in a persistent data store like Amazon DynamoDB (for durability and scalability) or Amazon ElastiCache (for low-latency access), the GenAI application can retrieve and provide contextually relevant responses across multiple turns. A session ID links requests to the correct conversation history. Option A (incorrect) would lead to a disjointed and frustrating user experience, as the assistant would lack context. Option B (incorrect) is insecure for sensitive information, has size limitations, and is not suitable for server-side state management. Option D (incorrect) foundation models, even fine-tuned, do not inherently maintain long-term conversation state across sessions; external memory is required for this purpose.', 64, 'm_64_6', 18, NULL, NULL),
  ('mock_64_all_1775005739332', 'A marketing team uses a generative AI model to create ad copy. They frequently experiment with different prompt variations to optimize engagement. To streamline this process and ensure consistency, they need a managed solution to store, version, and collaborate on prompts. Which Amazon Bedrock feature is designed to address this requirement?', '["Manually store prompts in a shared document on Amazon S3.","Utilize Amazon Bedrock Prompt Management to create, manage, and version prompt templates.","Hardcode prompt strings directly into the application''s source code.","Use AWS CodeCommit to version control prompt files alongside application code."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Bedrock Prompt Management, which is specifically designed for creating, managing, and versioning prompt templates. This feature allows teams to centralize prompts, collaborate on their development, and track changes, streamlining experimentation and ensuring consistency across GenAI applications. Option A (incorrect) is a manual and unmanaged approach that lacks versioning, collaboration features, and proper governance. Option C (incorrect) hardcoding prompts makes them difficult to update, manage, and experiment with, requiring code deployments for every change. Option D (incorrect) while AWS CodeCommit can version control files, it''s a generic code repository and doesn''t offer the specialized prompt management features (like templating, testing, and deployment workflows) that Bedrock Prompt Management provides.', 64, 'm_64_6', 19, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is developing a GenAI application that generates product descriptions. They need to ensure the generated content is high-quality, factually accurate, and free of hallucinations. The team wants to implement a systematic approach to evaluate and refine the model''s outputs over time. Which strategy is MOST effective for quality assurance and iterative refinement in this scenario?', '["Deploy the model and assume its outputs are always correct without further checks.","Implement a manual review process for a small sample of generated descriptions, with no systematic feedback loop.","Establish a human-in-the-loop feedback mechanism, collect user ratings and expert reviews, and use this data to iteratively fine-tune the model or refine prompts.","Only rely on automated metrics like perplexity to assess the quality of generated descriptions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a robust strategy for quality assurance and iterative refinement. Establishing a human-in-the-loop feedback mechanism, collecting user ratings, and expert reviews provides valuable data on output quality, factual accuracy, and hallucination rates. This feedback can then be used to iteratively refine prompts, adjust model parameters, or even fine-tune the model, leading to continuous improvement in generated content. Option A (incorrect) is a negligent approach that will likely lead to poor quality and inaccurate outputs. Option B (incorrect) a small, unsystematic sample review is insufficient for ensuring high quality and lacks a structured feedback loop for improvement. Option D (incorrect) automated metrics like perplexity are useful but do not fully capture factual accuracy, relevance, or subjective quality, which are critical for product descriptions.', 64, 'm_64_6', 20, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is developing a GenAI application that generates marketing content. They need to ensure that the generated content adheres to specific brand guidelines and avoids any offensive or inappropriate language. The team wants to implement a robust governance mechanism for prompt interactions. Which Amazon Bedrock feature allows for defining and enforcing content policies for model inputs and outputs?', '["Amazon Bedrock Prompt Management for organizing prompt templates.","Amazon Bedrock Guardrails for defining content policies and filtering harmful or off-topic content.","Fine-tuning the foundation model with a curated dataset of brand-compliant content.","Implementing a custom AWS Lambda function to filter model outputs based on a blacklist of words."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon Bedrock Guardrails, which is specifically designed to define and enforce content policies for both model inputs and outputs. It allows organizations to set up rules to filter out harmful, off-topic, or non-compliant content, ensuring that the generated marketing content adheres to brand guidelines and avoids inappropriate language. Option A (incorrect) Amazon Bedrock Prompt Management helps organize and version prompts, but it does not enforce content policies on model outputs. Option C (incorrect) fine-tuning can influence the model''s style, but it''s not a direct or foolproof mechanism for enforcing strict content policies and preventing all undesirable outputs. Option D (incorrect) a custom AWS Lambda function can filter outputs, but Bedrock Guardrails offers a more comprehensive, managed, and configurable solution for content moderation and policy enforcement.', 64, 'm_64_6', 21, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_64_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A data analytics firm is building a GenAI application that summarizes financial reports. They need to choose a foundation model that offers strong performance for summarization tasks while being cost-effective for high-volume processing. The firm wants to avoid vendor lock-in and retain the flexibility to switch models or providers if better options emerge. Which approach to model selection and configuration is MOST aligned with these goals?', '["Select a single, proprietary foundation model and hardcode its API endpoint into the application.","Use Amazon Bedrock to access multiple foundation models from different providers, leveraging model aliases or conditional routing for dynamic switching.","Deploy a custom open-source LLM on Amazon EC2 instances, managing all infrastructure and model updates.","Fine-tune a specific foundation model extensively for all summarization tasks, making it difficult to switch."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) uses Amazon Bedrock, which provides access to multiple foundation models from various providers. Leveraging model aliases or conditional routing allows for dynamic switching between models, offering flexibility, avoiding vendor lock-in, and enabling cost optimization by choosing the best-performing or most cost-effective model for specific tasks. Option A (incorrect) creates vendor lock-in and lacks flexibility to switch models or providers. Option C (incorrect) involves significant operational overhead for managing EC2 instances and custom LLMs, which is not cost-effective for high-volume processing compared to managed services. Option D (incorrect) extensive fine-tuning can create a strong dependency on a specific model, making it costly and time-consuming to switch to a different model or provider.', 64, 'm_64_2', 22, NULL, NULL),
  ('mock_64_all_1775005739332', 'A global enterprise is deploying a GenAI-powered customer service assistant that needs to be highly available and resilient across multiple AWS regions. In the event of a regional outage, the application must gracefully degrade or failover to another region with minimal impact on users. Which strategy for selecting and configuring FMs ensures the MOST resilience and graceful degradation?', '["Deploy the GenAI application and its foundation model in a single AWS Region, relying on AWS''s regional availability zones.","Configure Amazon Route 53 to route traffic to multiple Amazon Bedrock endpoints across different AWS Regions, with health checks and failover routing policies.","Deploy custom fine-tuned models on Amazon SageMaker in each region, with manual monitoring and failover procedures.","Use a single, large foundation model hosted by a third-party provider outside of AWS, with no regional redundancy."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides the most resilience and graceful degradation. By configuring Amazon Route 53 to route traffic to multiple Amazon Bedrock endpoints across different AWS Regions, with health checks and failover routing policies, the application can automatically direct users to a healthy region in case of an outage. Amazon Bedrock itself offers regional availability. Option A (incorrect) deploying in a single region does not protect against a regional outage, only against Availability Zone failures within that region. Option C (incorrect) involves manual failover procedures, which are not ideal for ''minimal impact on users'' and increase operational overhead. Option D (incorrect) introduces a single point of failure and lacks regional redundancy, making it highly vulnerable to outages.', 64, 'm_64_2', 23, NULL, NULL),
  ('mock_64_all_1775005739332', 'A startup is building a GenAI application for creative content generation. They want to fine-tune a foundation model with their proprietary dataset to generate content in a specific brand voice. The process needs to be efficient, cost-effective, and allow for iterative improvements without retraining the entire model. Which customization technique is MOST suitable for this scenario?', '["Retrain a foundation model from scratch using their proprietary dataset.","Use LoRA (Low-Rank Adaptation) with Amazon SageMaker to efficiently fine-tune the foundation model.","Manually adjust the model''s weights and biases after each generation to improve output.","Only rely on prompt engineering to guide the model''s output to match the brand voice."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is LoRA (Low-Rank Adaptation), a parameter-efficient fine-tuning technique. LoRA allows for efficient and cost-effective customization of foundation models by only training a small number of additional parameters, rather than retraining the entire model. This enables rapid iterative improvements and reduces computational resources, making it ideal for adapting a model to a specific brand voice without extensive retraining. Amazon SageMaker provides the infrastructure for this. Option A (incorrect) retraining a foundation model from scratch is extremely resource-intensive, time-consuming, and costly. Option C (incorrect) manually adjusting model weights is impractical and not a standard machine learning practice. Option D (incorrect) while prompt engineering is important, it may not be sufficient to fully capture a specific brand voice or achieve the desired level of customization without some form of model adaptation.', 64, 'm_64_2', 24, NULL, NULL),
  ('mock_64_all_1775005739332', 'A large enterprise is managing multiple custom fine-tuned foundation models for various internal applications. They need a centralized repository to track model versions, lineage, and metadata, and to facilitate automated deployment and rollback of these models. Which AWS service is designed to manage the full lifecycle of machine learning models, including GenAI models?', '["Amazon S3 for storing model artifacts and manual versioning.","AWS CodeCommit for version control of model code and configuration files.","Amazon SageMaker Model Registry to catalog, version, and manage the deployment of models.","AWS Systems Manager Parameter Store for storing model endpoint configurations."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon SageMaker Model Registry, which is specifically designed to catalog, version, and manage the full lifecycle of machine learning models, including custom fine-tuned GenAI models. It provides a centralized repository for tracking model versions, lineage, metadata, and facilitates automated deployment and rollback, ensuring governance and MLOps best practices. Option A (incorrect) Amazon S3 is object storage and lacks the specialized features for model versioning, lineage tracking, and deployment management. Option B (incorrect) AWS CodeCommit is a source code repository and not purpose-built for managing the lifecycle of deployed ML models. Option D (incorrect) AWS Systems Manager Parameter Store can store configurations but is not a comprehensive solution for model lifecycle management.', 64, 'm_64_2', 25, NULL, NULL);

