-- Module: m_65_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A startup is rapidly prototyping a web application that integrates a Generative AI model for content creation. They need a solution that provides a frontend hosting, backend API, authentication, and integration with an Amazon Bedrock Foundation Model, all with minimal development effort and operational overhead.', '["AWS Amplify, with its frontend hosting, API Gateway integration, and backend services, connecting to Amazon Bedrock.","Amazon EC2 instances running a custom web server, database, and manual integration with Amazon Bedrock.","AWS AppSync for real-time data synchronization, combined with custom Lambda functions for all backend logic.","Amazon S3 for static website hosting, with a separate Amazon API Gateway and AWS Lambda for dynamic content."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for rapid full-stack web and mobile application development. AWS Amplify provides integrated hosting for frontends, simplifies backend provisioning (including API Gateway, AWS Lambda, and authentication with Amazon Cognito), and offers SDKs for easy integration with services like Amazon Bedrock. This significantly reduces development effort and operational overhead for prototyping and deploying GenAI applications. Option B (incorrect) involves managing Amazon EC2 instances, databases, and manual integration, which significantly increases development effort and operational overhead. Option C (incorrect) focuses on real-time data synchronization and would still require significant custom development for the full application stack, including frontend hosting and authentication. Option D (incorrect) provides static website hosting but requires separate setup and management for authentication, dynamic backend APIs, and integration with Amazon Bedrock, leading to more development effort than Amplify.', 65, 'm_65_5', 12, NULL, NULL),
  ('mock_64_all_1775005739332', 'A software development company wants to accelerate its development cycle by leveraging Generative AI for code generation and debugging assistance. Developers need an integrated experience within their IDE to get real-time suggestions, explanations, and troubleshooting help.', '["Amazon SageMaker Studio for model development and deployment.","AWS CodePipeline for automated CI/CD workflows.","Amazon Q Developer, integrated into popular IDEs, for code generation and debugging.","AWS Lambda for serverless function execution and code snippets."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon Q Developer, which is specifically designed as an AI assistant for developers. It integrates directly into popular Integrated Development Environments (IDEs) like VS Code and JetBrains, providing real-time code suggestions, generating code based on natural language prompts, explaining code, and assisting with debugging and troubleshooting, thereby accelerating the development cycle. Option A (incorrect) is an integrated development environment for machine learning, focused on model building and training, not general software development assistance within an IDE. Option B (incorrect) is a continuous integration and continuous delivery service, focused on automating software release processes. Option D (incorrect) is a serverless compute service and while it executes code, it doesn''t provide AI-powered coding assistance within an IDE.', 65, 'm_65_5', 13, NULL, NULL),
  ('mock_64_all_1775005739332', 'A startup wants to quickly develop and deploy a web application that integrates with a Generative AI model for content generation. The team has limited frontend development experience and needs a solution that minimizes coding effort, provides a scalable backend, and includes built-in monitoring for prompt/response interactions.', '["AWS Amplify for frontend hosting and backend provisioning (API Gateway, Lambda), with Amazon CloudWatch and AWS X-Ray for observability of GenAI interactions.","Amazon EC2 instances for hosting the web application, with a custom Python Flask backend invoking the GenAI model, and Prometheus for monitoring.","AWS App Runner for deploying the web application container, with Amazon SQS for asynchronous GenAI model invocation, and custom logging to Amazon S3.","Amazon S3 for static website hosting, with a direct JavaScript call to the GenAI model API, and client-side logging to a third-party analytics service."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is ideal for rapid development with minimal coding. AWS Amplify provides a complete platform for building and deploying web applications, including frontend hosting and easy provisioning of serverless backend services like Amazon API Gateway and AWS Lambda to interact with GenAI models. Amazon CloudWatch and AWS X-Ray offer comprehensive observability for monitoring prompt/response latency, errors, and token usage, directly supporting the requirement for built-in monitoring.
Option B (incorrect) involves managing Amazon EC2 instances and a custom Flask backend, which significantly increases operational overhead and coding effort compared to Amplify''s managed services. Prometheus requires additional setup and management.
Option C (incorrect) uses AWS App Runner, which simplifies container deployment, but it doesn''t offer the comprehensive frontend development and backend provisioning capabilities of Amplify. Using Amazon SQS for asynchronous invocation is good for some scenarios, but the question implies a more interactive web application, and custom logging to S3 requires additional setup for analysis.
Option D (incorrect) uses Amazon S3 for static hosting, but direct client-side calls to a GenAI model API might expose API keys and would require significant client-side logic for security and error handling. Client-side logging to a third-party service might not provide the deep integration with AWS GenAI services needed for comprehensive prompt/response analysis.', 65, 'm_65_5', 14, NULL, NULL),
  ('mock_64_all_1775005739332', 'A team has deployed a Generative AI-powered chatbot that occasionally exhibits high latency and unexpected token usage. They need to analyze the prompt and response payloads, identify bottlenecks, and troubleshoot issues efficiently to improve the chatbot''s performance and cost-effectiveness.', '["Amazon CloudWatch Logs for storing raw prompt/response data, with Amazon Athena for querying the logs and Amazon QuickSight for visualization.","AWS Config for tracking resource changes, Amazon GuardDuty for threat detection, and AWS Trusted Advisor for cost optimization recommendations.","Amazon CloudWatch for metrics and logs, combined with AWS X-Ray for tracing requests across services and identifying performance bottlenecks.","Amazon S3 for storing prompt/response data, AWS Glue for ETL processing, and Amazon SageMaker Data Wrangler for data preparation and analysis."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most comprehensive solution for troubleshooting GenAI interactions. Amazon CloudWatch collects metrics (e.g., latency, error rates) and stores logs (including prompt and response payloads), allowing for detailed analysis. AWS X-Ray traces requests as they flow through various services (e.g., API Gateway, Lambda, GenAI model invocation), helping to pinpoint latency bottlenecks and identify which service is contributing most to the delay. This combination is specifically designed for application observability and performance analysis.
Option A (incorrect) uses CloudWatch Logs and Athena/QuickSight, which can analyze log data, but it lacks the distributed tracing capabilities of X-Ray to visualize the flow and identify bottlenecks across multiple services.
Option B (incorrect) lists services primarily focused on security, compliance, and cost optimization at an infrastructure level (AWS Config, GuardDuty, Trusted Advisor), which are not directly designed for analyzing prompt/response payloads or tracing application performance.
Option D (incorrect) focuses on data storage and preparation (Amazon S3, AWS Glue, SageMaker Data Wrangler), which is useful for large-scale data analysis or model training, but not the primary tools for real-time operational troubleshooting of application performance and tracing specific GenAI interactions.', 65, 'm_65_5', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_65_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A media company is building a real-time content summarization service that integrates with a foundational model API supporting streaming responses. The service needs to display summarized content to users as it becomes available, minimize perceived latency, and handle potential network interruptions gracefully.', '["Use the AWS SDK to invoke the streaming API, process chunks of the response asynchronously in an AWS Lambda function, and stream results back to the client via Amazon API Gateway with HTTP streaming.","Invoke the foundational model API synchronously from an Amazon EC2 instance, buffer the entire response, and then send it to the client once complete.","Implement a polling mechanism where the client repeatedly calls an Amazon API Gateway endpoint to check for new summary chunks from an Amazon SQS queue.","Use AWS Step Functions to orchestrate the foundational model invocation, store intermediate chunks in Amazon S3, and then trigger an AWS Lambda function to assemble and send the full response."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirements for streaming responses and minimizing perceived latency. The AWS SDK can handle streaming responses from foundational models. An AWS Lambda function can process these chunks as they arrive, and Amazon API Gateway supports HTTP streaming, allowing the summarized content to be sent to the client incrementally. This provides a responsive user experience and handles network interruptions gracefully by processing data in smaller, manageable parts.
Option B (incorrect) buffers the entire response, which defeats the purpose of streaming and increases perceived latency, especially for long summaries. Using an Amazon EC2 instance also adds operational overhead.
Option C (incorrect) uses a polling mechanism, which is inefficient, introduces unnecessary latency, and increases costs due to frequent requests, rather than leveraging the streaming capabilities of the foundational model.
Option D (incorrect) uses AWS Step Functions and Amazon S3 for orchestration and storage, which is suitable for batch processing or complex workflows, but introduces additional latency and complexity for a real-time streaming requirement. It does not directly support streaming the response to the client as it''s generated.', 65, 'm_65_4', 16, NULL, NULL),
  ('mock_64_all_1775005739332', 'A software vendor is developing an application that uses multiple foundational models (FMs) for different tasks. They need to dynamically route requests to the most appropriate FM based on the input prompt''s characteristics (e.g., length, complexity, specific keywords) or current cost-effectiveness, while ensuring high availability and resilience.', '["Hardcode the FM endpoint URLs directly into the application logic and use conditional statements to select the appropriate model.","Deploy a single Amazon API Gateway endpoint that directly proxies requests to a pre-configured, static foundational model endpoint.","Implement an AWS Lambda function behind Amazon API Gateway to dynamically select and invoke the FM using the AWS SDK, with built-in retry logic and fallbacks.","Use Amazon EventBridge to route events to different AWS Lambda functions, each hardcoded to invoke a specific foundational model, based on predefined event patterns and static routing rules."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides a flexible, scalable, and resilient solution for intelligent model routing. An AWS Lambda function can act as a router, analyzing the input prompt''s characteristics or external factors (like cost) to dynamically select the optimal foundational model. It can then invoke the chosen model using the AWS SDK, incorporating resilience patterns like retry logic and fallbacks. Amazon API Gateway provides a unified, highly available endpoint for the application.
Option A (incorrect) hardcodes FM endpoints, making the solution inflexible, difficult to update, and lacking dynamic routing capabilities. It also doesn''t provide resilience or fallback mechanisms.
Option B (incorrect) uses a single Amazon API Gateway endpoint that proxies to a static FM, which does not allow for dynamic routing based on input characteristics or cost optimization.
Option D (incorrect) uses Amazon EventBridge for routing, but EventBridge rules are typically based on static patterns in event payloads, not dynamic analysis of a prompt''s content or real-time cost factors. While it can route to different Lambda functions, the dynamic decision-making logic would still need to reside within Lambda, making a direct API Gateway -> Lambda -> FM approach more straightforward for this specific use case.', 65, 'm_65_4', 17, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_65_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A data science team has fine-tuned a large foundational model for a specialized natural language understanding task. They need to deploy this model for real-time inference, ensuring predictable latency, high throughput, and cost optimization for a consistent, high volume of requests.', '["Amazon SageMaker Serverless Inference endpoint, as it automatically scales and minimizes idle costs.","Amazon SageMaker Batch Transform job, as it''s designed for processing large datasets asynchronously.","Amazon SageMaker Asynchronous Inference endpoint, which is optimized for handling large payload sizes and long processing times, storing results in Amazon S3.","Amazon SageMaker Real-time Endpoint with Provisioned Throughput, configured with suitable instance types and autoscaling policies for consistent performance."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most suitable strategy for real-time inference with predictable latency and high throughput for a consistent, high volume of requests. Amazon SageMaker Real-time Endpoints provide dedicated, always-on compute resources. Provisioned Throughput ensures that a specific capacity is reserved, guaranteeing predictable performance and latency, which is crucial for consistent, high-volume workloads. Autoscaling policies can be added to handle minor fluctuations above the provisioned baseline.
Option A (incorrect) Amazon SageMaker Serverless Inference is cost-effective for intermittent or unpredictable traffic with cold starts, but it does not guarantee predictable latency and throughput for consistent, high-volume workloads due to its on-demand scaling nature.
Option B (incorrect) Amazon SageMaker Batch Transform is designed for offline, asynchronous processing of large datasets, not for real-time, low-latency inference.
Option C (incorrect) Amazon SageMaker Asynchronous Inference is optimized for large payload sizes and long processing times where immediate responses are not required. It processes requests in a queue and returns results later, which is not suitable for real-time, low-latency requirements.', 65, 'm_65_2', 18, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company has deployed a Generative AI model endpoint that experiences highly variable traffic patterns, with predictable peak hours and significant idle periods. The goal is to optimize costs while maintaining responsiveness during peak demand and avoiding cold starts for critical requests.', '["Deploy the model on an Amazon EC2 instance and manually scale it up and down based on traffic forecasts, requiring custom monitoring and scripting.","Utilize an Amazon SageMaker Real-time Endpoint configured with Provisioned Throughput for baseline capacity and Serverless Inference for burst capacity.","Use Amazon SageMaker Serverless Inference exclusively, relying on its automatic scaling to handle all traffic variations.","Implement an Amazon SageMaker Batch Transform job that runs periodically to process accumulated requests."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective strategy for balancing cost optimization and performance with highly variable traffic patterns, especially with predictable peaks and idle periods. Using Amazon SageMaker Real-time Endpoint with Provisioned Throughput provides a consistent baseline capacity, ensuring responsiveness and avoiding cold starts for critical requests during predictable peaks. Supplementing this with Serverless Inference for burst capacity allows the endpoint to handle unexpected spikes or additional load beyond the provisioned baseline in a cost-effective manner, as Serverless Inference scales on demand and charges only for active usage.
Option A (incorrect) deploying on Amazon EC2 instances and manual scaling introduces significant operational overhead and is prone to human error, making it less efficient for cost and performance optimization compared to managed SageMaker services.
Option C (incorrect) using Amazon SageMaker Serverless Inference exclusively is cost-effective during idle periods but can introduce cold starts and potentially higher latency during peak demand due to its on-demand scaling model, which might not meet the responsiveness requirements for critical requests.
Option D (incorrect) Amazon SageMaker Batch Transform is designed for asynchronous, batch processing, not for real-time inference with responsiveness requirements.', 65, 'm_65_2', 19, NULL, NULL);

