INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A financial institution is deploying a generative AI application using Amazon Bedrock for customer service interactions. Due to strict regulatory requirements, all model invocations, including prompts and responses, must be logged for audit and compliance purposes for at least seven years. The solution must also ensure minimal operational overhead. Which approach meets these requirements MOST effectively?', '["Enable Amazon Bedrock Model Invocation Logging to Amazon CloudWatch Logs and configure a CloudWatch Logs subscription filter to stream logs to an Amazon S3 bucket for long-term archival.","Implement custom logging within the application code to capture prompts and responses, then store them directly in an Amazon S3 bucket with appropriate lifecycle policies.","Use AWS CloudTrail to log all Amazon Bedrock API calls and configure a CloudTrail trail to deliver logs to an Amazon S3 bucket for audit and compliance.","Configure Amazon CloudWatch metrics for Amazon Bedrock usage and set up alarms to notify an AWS Lambda function, which then logs invocation details to Amazon DynamoDB."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective approach. Amazon Bedrock Model Invocation Logging directly captures prompts and responses, which is crucial for audit and compliance. Integrating with Amazon CloudWatch Logs provides a managed service for log ingestion and retention, and then streaming to Amazon S3 for long-term archival with lifecycle policies ensures the seven-year retention requirement with minimal operational overhead. Option B (incorrect) involves significant custom development and maintenance for logging, which increases operational overhead and might miss certain invocation details managed by Bedrock itself. Option C (incorrect) AWS CloudTrail logs API calls made to Amazon Bedrock, but it does not capture the actual prompts and responses exchanged with the generative AI models, which are essential for content-level auditing. Option D (incorrect) Amazon CloudWatch metrics provide aggregate usage data, not detailed invocation logs (prompts and responses). Using an AWS Lambda function to log to Amazon DynamoDB would be a complex and high-overhead solution for detailed invocation logging, and DynamoDB is not typically cost-effective for long-term, high-volume log archival compared to Amazon S3.', 66, 'm_66_3', 1, NULL, NULL),
  ('mock_64_all_1775005739332', 'A healthcare provider is building a generative AI application on Amazon Bedrock to assist medical staff with information retrieval. The organization requires a robust governance framework to ensure that only authorized personnel can invoke specific models and that all model usage is traceable. The solution must enforce least privilege access. Which combination of services should be used to achieve this?', '["Utilize Amazon CloudWatch to monitor model invocation metrics and create custom dashboards for auditing access patterns.","Implement AWS IAM policies to control access to specific Amazon Bedrock models and enable Amazon Bedrock Model Invocation Logging for detailed audit trails.","Configure AWS PrivateLink for Amazon Bedrock to restrict model access to specific VPCs and use AWS Config rules to monitor IAM policy changes.","Deploy an AWS Lambda authorizer in front of the Amazon Bedrock API calls to validate user identity and log access attempts to Amazon S3."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the requirements. AWS IAM policies are the standard and most effective way to enforce least privilege access to specific Amazon Bedrock models, ensuring only authorized personnel can invoke them. Amazon Bedrock Model Invocation Logging provides the detailed audit trails of prompts and responses, making model usage traceable for governance and compliance. Option A (incorrect) Amazon CloudWatch monitors metrics but does not enforce access control or provide detailed invocation logs for traceability. Option C (incorrect) AWS PrivateLink secures network connectivity to Amazon Bedrock but does not enforce user-level authorization or provide audit trails of model usage content. AWS Config monitors resource configurations, not real-time access decisions or content. Option D (incorrect) Deploying an AWS Lambda authorizer would add significant operational overhead and complexity, as Amazon Bedrock already integrates with AWS IAM for robust access control. This is an unnecessary custom solution for a problem already solved by native AWS services.', 66, 'm_66_3', 2, NULL, NULL),
  ('mock_64_all_1775005739332', 'A global e-commerce company is developing a generative AI chatbot using Amazon Bedrock to handle customer inquiries. The company operates in multiple regions and must comply with various data residency and privacy regulations. To ensure compliance, they need to establish clear traceability of all data (prompts and responses) processed by the models. Which solution provides the necessary traceability and supports compliance requirements with minimal custom development?', '["Store all prompts and responses in a regional Amazon S3 bucket, using S3 object tagging to categorize data by compliance requirements.","Implement Amazon CloudWatch Logs for application-level logging of prompts and responses, then use AWS Glue Data Catalog to manage metadata for traceability.","Enable Amazon Bedrock Model Invocation Logging to Amazon CloudWatch Logs, configure regional log groups, and use AWS CloudTrail for API call auditing.","Develop a custom data pipeline using AWS Step Functions to capture prompts and responses, then store them in Amazon DynamoDB with time-to-live (TTL) attributes."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most straightforward and effective approach. Enabling Amazon Bedrock Model Invocation Logging captures the actual prompts and responses, which can be configured to send logs to regional Amazon CloudWatch Logs log groups, directly addressing data residency. AWS CloudTrail then provides an audit trail of API calls made to Bedrock, complementing the content logging for comprehensive compliance. This combination offers robust traceability with minimal custom development. Option A (incorrect) storing raw data in Amazon S3 with tagging provides some traceability but lacks the automatic capture of invocation details and the structured audit trail provided by Bedrock''s native logging and CloudTrail. Option B (incorrect) Amazon CloudWatch Logs for application-level logging requires custom implementation, and AWS Glue Data Catalog is primarily for data discovery and metadata management, not for capturing real-time invocation content. Option D (incorrect) developing a custom data pipeline with AWS Step Functions and Amazon DynamoDB would introduce significant operational overhead and complexity, duplicating functionality already available natively through Amazon Bedrock''s logging capabilities.', 66, 'm_66_3', 3, NULL, NULL),
  ('mock_64_all_1775005739332', 'A technology company is using Amazon Bedrock to power an internal knowledge base chatbot. They need to ensure that all interactions with the generative AI models are auditable for internal policy compliance and to detect any potential misuse. The solution must capture both the input prompts and the generated responses reliably. Which AWS service combination best achieves this goal?', '["Use AWS CloudTrail to log all Bedrock API calls and Amazon CloudWatch to monitor Bedrock usage metrics.","Implement an AWS Lambda function to intercept all Bedrock API calls, log the request and response payloads to Amazon S3, and then forward the original request.","Configure Amazon Bedrock Guardrails to filter content and use Amazon CloudWatch Logs to store Guardrails activity logs.","Enable Amazon Bedrock Model Invocation Logging to send prompt and response data to Amazon CloudWatch Logs, and then optionally archive to Amazon S3 for long-term storage."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the most direct and efficient way to capture both input prompts and generated responses for auditing. Amazon Bedrock Model Invocation Logging is specifically designed for this purpose, providing detailed logs of the actual content exchanged with the models. Sending these logs to Amazon CloudWatch Logs ensures reliable storage and easy access, with optional archiving to Amazon S3 for long-term retention. Option A (incorrect) AWS CloudTrail logs API calls but does not capture the actual content of prompts and responses. Amazon CloudWatch monitors metrics, not detailed invocation content. Option B (incorrect) intercepting API calls with an AWS Lambda function is a custom, high-overhead solution that duplicates the functionality of Amazon Bedrock''s native invocation logging and introduces potential latency and failure points. Option C (incorrect) Amazon Bedrock Guardrails focuses on content filtering and safety, and while it generates logs, it does not provide comprehensive logging of all raw prompts and responses for audit purposes, only the interactions with the guardrails themselves.', 66, 'm_66_3', 4, NULL, NULL),
  ('mock_64_all_1775005739332', 'A government agency is developing a secure internal generative AI application using Amazon Bedrock. They require a comprehensive governance strategy to ensure that all interactions with the models are compliant with data handling policies and that an immutable audit trail exists for every invocation. The solution needs to minimize administrative effort. Which approach best satisfies these requirements?', '["Enable Amazon Bedrock Model Invocation Logging to an encrypted Amazon S3 bucket, configured with object lock and lifecycle policies for immutability and retention.","Implement application-level logging that writes prompts and responses to an Amazon DynamoDB table, then use AWS CloudTrail to monitor DynamoDB access.","Utilize AWS Config to monitor changes to Amazon Bedrock model configurations and send notifications to an Amazon SNS topic.","Set up Amazon CloudWatch metrics for Bedrock usage and create custom alarms to detect unusual invocation patterns, indicating potential policy violations."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most effective and low-overhead solution. Amazon Bedrock Model Invocation Logging directly captures the prompts and responses, which is essential for compliance and audit. Sending these logs to an encrypted Amazon S3 bucket with Object Lock ensures immutability, while lifecycle policies manage retention, meeting the audit trail requirements with minimal administrative effort. Option B (incorrect) implementing application-level logging to Amazon DynamoDB introduces significant custom development and operational overhead, and DynamoDB is not optimized for immutable, long-term log archival compared to Amazon S3. AWS CloudTrail monitors DynamoDB access, not the content of the logs. Option C (incorrect) AWS Config monitors configuration changes, not the actual content of model invocations or user interactions, which is critical for data handling compliance. Option D (incorrect) Amazon CloudWatch metrics provide aggregate usage data and can detect patterns, but they do not capture the detailed content of prompts and responses required for an immutable audit trail of every invocation.', 66, 'm_66_3', 5, NULL, NULL);

