INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A marketing agency uses Amazon Bedrock to generate ad copy. They are concerned about potential biases in the model''s output leading to unfair or stereotypical representations in their campaigns. The agency needs a mechanism to evaluate and mitigate bias in the generated content. Which approach helps address bias and fairness considerations?', '["Increase the creativity parameter (temperature) of the foundation model to produce more diverse outputs.","Implement a post-processing step using Amazon Comprehend to detect sentiment and adjust ad copy accordingly.","Conduct regular human review of generated ad copy for bias, and use Amazon Bedrock Guardrails to enforce policy-compliant outputs.","Fine-tune the foundation model on a larger, more diverse dataset of ad copy to reduce inherent biases."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is a practical and effective approach for addressing bias and fairness in generated content. Regular human review is crucial for identifying subtle biases that automated systems might miss, especially in subjective areas like marketing. Using Amazon Bedrock Guardrails to enforce policy-compliant outputs can help prevent the generation of content that violates fairness guidelines, acting as a programmatic safety net. Option A (incorrect) increasing temperature might lead to more diverse outputs but does not guarantee the reduction or mitigation of systemic biases; it could even introduce new ones. Option B (incorrect) Amazon Comprehend detects sentiment, which is different from identifying and mitigating bias related to fairness or representation. Option D (incorrect) while fine-tuning on a diverse dataset can help reduce inherent biases, it''s a resource-intensive process, and continuous monitoring and enforcement (like human review and Guardrails) are still necessary to ensure ongoing fairness and address emergent biases.', 66, 'm_66_4', 16, NULL, NULL),
  ('mock_64_all_1775005739332', 'A news organization uses Amazon Bedrock to generate factual summaries of articles. To maintain journalistic integrity, they need to ensure transparency by providing source attribution for all generated facts and mitigating hallucinations. Which architectural pattern should be implemented?', '["Implement a Retrieval Augmented Generation (RAG) architecture, retrieving information from a trusted article database and configuring Amazon Bedrock Guardrails for grounding and citation-based responses.","Fine-tune the foundation model on a vast dataset of news articles, relying on the model''s internal knowledge to generate accurate summaries.","Use an AWS Lambda function to post-process the generated summaries, cross-referencing facts with external search engines for verification.","Increase the model''s ''top_p'' parameter to broaden the range of possible tokens, encouraging more diverse and less repetitive summaries."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective architectural pattern for achieving source attribution and mitigating hallucinations. A Retrieval Augmented Generation (RAG) architecture ensures that the generative AI model bases its responses on specific, trusted source documents (the article database). Configuring Amazon Bedrock Guardrails for grounding further enforces this by ensuring responses are tied to the provided context and can generate citation-based responses, directly supporting journalistic integrity and transparency. Option B (incorrect) fine-tuning can improve model performance but does not inherently provide source attribution or guarantee the elimination of hallucinations, especially for new or evolving information. Option C (incorrect) using an AWS Lambda function for post-processing and external search engine verification would be complex, slow, and less reliable than directly grounding the model''s generation process. Option D (incorrect) increasing ''top_p'' influences the diversity of generated text but does not address factual accuracy, hallucination mitigation, or source attribution.', 66, 'm_66_4', 17, NULL, NULL),
  ('mock_64_all_1775005739332', 'An insurance company uses Amazon Bedrock to generate policy explanations for customers. They need to ensure that the generated explanations strictly adhere to legal and compliance policies, avoiding any misleading or incorrect information. The solution must provide a mechanism to enforce these rules programmatically. Which approach is most suitable?', '["Implement a manual review process for all generated policy explanations before they are sent to customers.","Configure Amazon Bedrock Guardrails with custom word filters and topic denial rules based on legal and compliance policies.","Train a custom Amazon SageMaker model to classify policy explanations for compliance and reject non-compliant ones.","Use Amazon Comprehend to detect the sentiment of generated explanations and ensure they are always positive."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most suitable programmatic approach. Amazon Bedrock Guardrails allow you to define custom word filters to block specific terms or phrases that might violate policies, and topic denial rules to prevent the model from discussing sensitive or prohibited subjects. This directly helps enforce legal and compliance policies in the generated outputs. Option A (incorrect) a manual review process is essential but does not scale well and is prone to human error; it''s not a programmatic enforcement mechanism. Option C (incorrect) training a custom Amazon SageMaker model for compliance classification would be a complex, resource-intensive, and time-consuming undertaking, and it would act as a post-generation filter rather than preventing non-compliant content from being generated in the first place. Option D (incorrect) Amazon Comprehend detects sentiment, which is not the same as enforcing legal or compliance accuracy in policy explanations.', 66, 'm_66_4', 18, NULL, NULL),
  ('mock_64_all_1775005739332', 'A non-profit organization is developing a generative AI tool to assist with grant application writing. They are committed to responsible AI practices and need to ensure the tool''s outputs are fair and do not inadvertently introduce or amplify biases related to protected characteristics (e.g., gender, race). Which strategy is crucial for evaluating and addressing fairness in this context?', '["Increase the diversity of the input prompts to cover a wider range of grant application scenarios.","Implement a post-processing step to rephrase any sentences that appear to be overly positive or negative.","Establish a diverse human evaluation panel to review generated grant applications for bias and provide qualitative feedback.","Utilize Amazon CloudWatch metrics to monitor the frequency of specific keywords in the generated text."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is crucial for evaluating and addressing fairness. Bias detection and fairness considerations often require human judgment, especially in nuanced applications like grant writing where subtle biases can have significant impacts. A diverse human evaluation panel can identify and provide qualitative feedback on biases related to protected characteristics that automated tools might miss, directly contributing to responsible AI practices. Option A (incorrect) increasing prompt diversity is a good practice but doesn''t guarantee bias mitigation in outputs; the model might still generate biased content from diverse inputs. Option B (incorrect) rephrasing sentences based on sentiment is not a direct method for addressing fairness or systemic bias related to protected characteristics. Option D (incorrect) monitoring keyword frequency with Amazon CloudWatch metrics is a quantitative measure that might indicate some patterns but is insufficient for comprehensively evaluating and addressing complex issues of fairness and bias in generative AI outputs.', 66, 'm_66_4', 19, NULL, NULL),
  ('mock_64_all_1775005739332', 'A content creation company uses Amazon Bedrock to generate articles. They want to ensure that the articles are factually accurate and that the model does not ''hallucinate'' information. The company also wants to provide confidence scores for the generated facts to promote transparency. Which approach best achieves these goals for responsible AI?', '["Fine-tune the foundation model on a curated dataset of fact-checked articles to improve its inherent factual knowledge.","Use Amazon Comprehend to analyze the generated articles for factual consistency against a predefined set of rules.","Implement a Retrieval Augmented Generation (RAG) architecture with a trusted knowledge base and use Amazon Bedrock Guardrails for grounding, along with a mechanism to quantify uncertainty.","Configure Amazon CloudWatch to monitor the length of generated articles and flag unusually short ones for manual review."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) is the most comprehensive approach for factual accuracy, hallucination mitigation, and transparency (confidence scores). A Retrieval Augmented Generation (RAG) architecture grounds the model''s responses in a trusted knowledge base, significantly reducing hallucinations. Amazon Bedrock Guardrails can further enforce grounding and, when combined with techniques for uncertainty quantification (like confidence scoring), provides transparency regarding the reliability of generated facts, aligning with responsible AI principles. Option A (incorrect) fine-tuning can improve factual knowledge but doesn''t eliminate hallucinations or provide confidence scores for individual facts. Option B (incorrect) Amazon Comprehend is for text analysis (sentiment, entities) and is not designed for complex factual consistency checks against external knowledge or for providing confidence scores. Option D (incorrect) monitoring article length is irrelevant to factual accuracy, hallucination, or confidence scoring.', 66, 'm_66_4', 20, NULL, NULL);

