INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A company is developing a GenAI application that uses a large language model (LLM) for content generation. They anticipate high invocation rates but need to minimize inference costs, especially for repetitive prompts or common queries. The solution must reduce redundant LLM calls by storing and reusing previous responses. Which approach offers the MOST cost-effective way to achieve this?', '["Implement a semantic caching layer using Amazon DynamoDB and AWS Lambda to store and retrieve LLM responses for similar prompts.","Manually review and pre-generate responses for all anticipated common queries, storing them in Amazon S3 for direct retrieval.","Configure the LLM to automatically detect and skip redundant computations, relying on the model''s internal optimization features.","Deploy a dedicated Amazon EC2 instance with a custom caching solution, managing cache invalidation and storage manually."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) describes implementing a semantic caching layer. This approach is highly cost-effective because it reduces the number of expensive LLM invocations by serving responses from a cache for similar or identical prompts. Using Amazon DynamoDB provides a scalable, low-cost key-value store, and AWS Lambda can manage the caching logic with a pay-per-use model, minimizing operational overhead and cost. Option B (incorrect) is not scalable or practical for a dynamic GenAI application, as manually pre-generating responses for all common queries is labor-intensive and cannot adapt to evolving prompts. Option C (incorrect) relies on an assumption that LLMs have built-in, effective redundancy detection and skipping mechanisms, which is generally not a primary feature for cost optimization at the inference layer. LLMs focus on generation, not external caching. Option D (incorrect) involves deploying and managing a dedicated Amazon EC2 instance, which introduces significant operational overhead and higher fixed costs compared to a serverless caching solution, failing the ''MOST cost-effective'' constraint.', 67, 'm_67_1', 1, NULL, NULL),
  ('mock_64_all_1775005739332', 'A startup is building a GenAI-powered chatbot for customer support. Initial testing shows that many user queries are similar, leading to repeated expensive LLM inferences. They want to implement a strategy to reduce these redundant calls and lower operational costs while maintaining response accuracy. Which solution offers the LEAST operational overhead?', '["Set up a custom caching mechanism on an Amazon EC2 instance, using Redis for in-memory storage and managing cache invalidation manually.","Utilize Amazon DynamoDB as a deterministic cache for exact prompt-response pairs, integrating with AWS Lambda for cache lookup before LLM invocation.","Employ Amazon ElastiCache for Redis to store semantic embeddings of prompts and their responses, requiring custom logic for similarity matching and cache updates.","Implement a prompt compression algorithm using a separate machine learning model deployed on Amazon SageMaker, reducing token count before sending to the LLM."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) involves using Amazon DynamoDB as a deterministic cache for exact prompt-response pairs, integrated with AWS Lambda. This approach offers the least operational overhead because DynamoDB is a fully managed NoSQL database, and AWS Lambda is a serverless compute service. This combination requires minimal setup and maintenance, as AWS handles the underlying infrastructure, scaling, and patching. Option A (incorrect) requires managing an Amazon EC2 instance and a Redis cluster, which significantly increases operational overhead due to server maintenance, patching, and manual cache invalidation logic. Option C (incorrect) uses Amazon ElastiCache for Redis, which is managed, but still requires custom logic for semantic embedding, similarity matching, and complex cache invalidation, adding more operational complexity than a simple deterministic cache. Option D (incorrect) introduces an additional machine learning model and SageMaker endpoint, which adds complexity, cost, and operational overhead for managing another model, rather than directly caching LLM responses.', 67, 'm_67_1', 2, NULL, NULL),
  ('mock_64_all_1775005739332', 'A data science team is fine-tuning a large language model on Amazon SageMaker for a specific domain. They need to optimize the inference endpoint for cost efficiency, as the application will experience varying traffic patterns with occasional spikes. The primary goal is to pay only for actual usage while handling bursts. Which SageMaker endpoint configuration is MOST cost-effective for this scenario?', '["Deploy the model to a SageMaker Real-Time Endpoint with a single ml.g4dn.xlarge instance and disable autoscaling.","Use SageMaker Asynchronous Inference with a minimum instance count of 1 and a maximum instance count of 5.","Configure a SageMaker Real-Time Endpoint with autoscaling enabled, setting a minimum instance count of 0 and a maximum instance count appropriate for peak load.","Utilize SageMaker Batch Transform jobs scheduled hourly to process incoming requests from an Amazon S3 bucket."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes configuring a SageMaker Real-Time Endpoint with autoscaling enabled, setting a minimum instance count of 0 and a maximum instance count appropriate for peak load. This is the most cost-effective solution for varying traffic patterns because it allows the endpoint to scale down to zero instances when not in use, eliminating costs during idle periods, and scales up automatically to handle spikes. Option A (incorrect) uses a fixed instance count without autoscaling, leading to unnecessary costs during low traffic and potential performance issues during high traffic. Option B (incorrect) uses SageMaker Asynchronous Inference, which is designed for requests with large payload sizes or long processing times, not typically for real-time, interactive applications with varying traffic and a need for immediate responses. While it can scale, its primary use case and cost model differ from real-time interactive needs. Option D (incorrect) uses SageMaker Batch Transform, which is suitable for offline, non-interactive processing of large datasets, not for real-time interactive inference that requires immediate responses.', 67, 'm_67_1', 3, NULL, NULL),
  ('mock_64_all_1775005739332', 'An enterprise is deploying a GenAI application that processes user queries and generates summaries. They have identified that a significant portion of prompts can be compressed without losing semantic meaning, reducing token count. They need an automated method to achieve this before sending prompts to the LLM. Which approach will MAXIMIZE token efficiency with minimal impact on prompt quality?', '["Implement a manual review process where human operators rewrite prompts to be more concise before submission.","Use a pre-trained smaller language model or a specialized prompt compression model to rewrite prompts, invoked via AWS Lambda.","Configure the GenAI application to truncate prompts exceeding a certain character limit, discarding excess information.","Instruct the main LLM to self-compress the prompt as part of its initial processing, adding an extra step to the LLM''s workload."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) involves using a pre-trained smaller language model or a specialized prompt compression model, invoked via AWS Lambda, to rewrite prompts. This approach maximizes token efficiency by intelligently reducing the prompt''s length while preserving semantic meaning, which is critical for maintaining prompt quality. AWS Lambda provides a serverless, scalable way to execute this compression logic. Option A (incorrect) is a manual process that does not scale and introduces significant operational overhead, making it unsuitable for an automated GenAI application. Option C (incorrect) involves simple truncation, which can easily lead to loss of critical information and degrade prompt quality, failing to preserve semantic meaning. Option D (incorrect) adds an extra task to the main LLM, which would increase its processing time and token usage for the compression step itself, potentially negating the efficiency gains and increasing latency and cost.', 67, 'm_67_1', 4, NULL, NULL),
  ('mock_64_all_1775005739332', 'A media company uses a GenAI model to generate article drafts. They have multiple models of varying complexity and cost. For common, less critical tasks, they want to use a smaller, cheaper model, while reserving the larger, more expensive model for complex or high-priority requests. Which strategy should they implement to OPTIMIZE cost based on task complexity?', '["Implement a model routing layer using AWS Lambda that evaluates incoming requests and directs them to the appropriate model based on predefined rules or a classification model.","Deploy only the largest, most capable model and rely on prompt engineering to instruct it to behave like a smaller model for simpler tasks.","Manually switch between different SageMaker endpoints for each task type, requiring developers to update the application code for every request.","Use Amazon API Gateway to create separate endpoints for each model, and then manually configure client applications to choose the correct endpoint."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) describes implementing a model routing layer using AWS Lambda that evaluates incoming requests and directs them to the appropriate model based on predefined rules or a classification model. This approach directly addresses the need to optimize cost by dynamically selecting the most cost-effective model for each task, based on its complexity. AWS Lambda provides a scalable and serverless way to implement this routing logic. Option B (incorrect) would mean using the most expensive model for all tasks, which is not cost-optimal, even with prompt engineering, as larger models consume more resources. Option C (incorrect) involves manual switching, which is not scalable, introduces operational overhead, and is prone to errors in a dynamic environment. Option D (incorrect) requires client applications to handle the routing logic, which pushes complexity to the client side and makes it harder to manage and update the routing strategy centrally, and does not automate the decision-making process for model selection.', 67, 'm_67_1', 5, NULL, NULL),
  ('mock_64_all_1775005739332', 'A financial institution is developing a GenAI application that performs sentiment analysis on market news. They need to process a large volume of news articles daily, but not in real-time. The goal is to minimize inference costs by processing these articles in an efficient, non-interactive manner. Which AWS service combination is MOST suitable for MINIMIZING inference costs for this batch processing workload?', '["Deploy the sentiment analysis model to an Amazon SageMaker Real-Time Endpoint with a high minimum instance count to ensure immediate availability.","Store news articles in an Amazon S3 bucket and use Amazon SageMaker Batch Transform to process them periodically, writing results back to S3.","Use AWS Lambda to invoke the sentiment analysis model for each article individually as soon as it arrives, ensuring low latency.","Run the sentiment analysis model on an Amazon EC2 instance, manually managing the batch processing script and scaling the instance as needed."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) involves storing news articles in an Amazon S3 bucket and using Amazon SageMaker Batch Transform to process them periodically, writing results back to S3. This is the most cost-effective solution for non-real-time, large-volume batch processing. SageMaker Batch Transform is designed to process data efficiently in batches, and you only pay for the compute resources used during the batch job, eliminating the need for always-on endpoints. Option A (incorrect) uses a SageMaker Real-Time Endpoint, which is designed for interactive, low-latency inference and would be significantly more expensive for a non-real-time batch workload, especially with a high minimum instance count. Option C (incorrect) uses AWS Lambda for individual article processing, which can be cost-effective for smaller, event-driven workloads, but for a large volume of non-real-time articles, the overhead of individual invocations can accumulate, and it''s not optimized for large batch throughput like Batch Transform. Option D (incorrect) requires manual management of an Amazon EC2 instance, including scaling, patching, and script execution, which increases operational overhead and can be less cost-efficient than a managed service like SageMaker Batch Transform.', 67, 'm_67_1', 6, NULL, NULL),
  ('mock_64_all_1775005739332', 'A developer is building a GenAI application that interacts with an LLM for code generation. They observe that many code snippets are frequently requested. To reduce latency and cost for these common requests, they want to store and retrieve previously generated outputs. Which approach best provides a semantic caching layer for deterministic outputs?', '["Use Amazon S3 to store generated code snippets, with an AWS Lambda function to check S3 before invoking the LLM.","Implement a custom cache on an Amazon EC2 instance using an in-memory database like Redis, managing cache invalidation manually.","Utilize Amazon DynamoDB to store prompt-hash-response mappings, where the hash represents the semantic meaning of the prompt, and retrieve responses via AWS Lambda.","Configure the LLM to include a ''cache'' parameter in its invocation, relying on the underlying model provider to handle caching."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes utilizing Amazon DynamoDB to store prompt-hash-response mappings, where the hash represents the semantic meaning of the prompt, and retrieving responses via AWS Lambda. This is an effective way to implement a semantic caching layer for deterministic outputs. DynamoDB offers low-latency access and scalability, and using a hash of the prompt allows for efficient lookup of semantically similar requests. AWS Lambda provides the serverless compute for cache management. Option A (incorrect) uses Amazon S3, which is object storage and not optimized for low-latency key-value lookups required for a cache. While possible, it''s less efficient than DynamoDB. Option B (incorrect) involves managing an Amazon EC2 instance and Redis, which increases operational overhead and complexity compared to fully managed services. Option D (incorrect) relies on a hypothetical ''cache'' parameter within the LLM, which is not a standard or widely available feature for external caching and would not provide the developer with control over the caching strategy.', 67, 'm_67_1', 7, NULL, NULL);

