INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A company has deployed a GenAI application that uses Amazon Bedrock for text generation. They need to monitor the application''s performance and identify potential issues like high latency or errors in real-time. Specifically, they want to track the number of invocations and response times for the Bedrock models. Which monitoring solution is MOST effective for REAL-TIME operational visibility?', '["Periodically download Amazon Bedrock model invocation logs from Amazon S3 and analyze them using a custom script.","Implement custom metrics in AWS CloudWatch by parsing application logs for invocation details and response times.","Use AWS X-Ray to trace individual requests through the entire application stack, including Bedrock invocations.","Leverage Amazon CloudWatch metrics automatically emitted by Amazon Bedrock for model invocations and latency, and create CloudWatch Alarms."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) involves leveraging Amazon CloudWatch metrics automatically emitted by Amazon Bedrock for model invocations and latency, and creating CloudWatch Alarms. This is the most effective solution for real-time operational visibility because Bedrock integrates directly with CloudWatch, providing out-of-the-box metrics without any custom implementation. CloudWatch Alarms can then provide immediate notifications for anomalies or threshold breaches. Option A (incorrect) relies on periodic log downloads from Amazon S3, which is not a real-time monitoring solution and introduces significant delay in detecting issues. Option B (incorrect) requires custom implementation of metrics by parsing application logs, which adds operational overhead and might not capture all Bedrock-specific metrics as efficiently as native integration. Option C (incorrect) uses AWS X-Ray for tracing, which is excellent for end-to-end request visibility and debugging, but CloudWatch metrics are more suitable for aggregate real-time performance monitoring and alerting on specific metrics like invocation counts and latency.', 67, 'm_67_3', 8, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI chatbot application is experiencing occasional ''hallucinations'' where it generates factually incorrect information. The development team needs to implement a monitoring solution to detect and quantify these occurrences to improve model reliability. They want to analyze model outputs over time. Which approach is MOST suitable for IDENTIFYING and tracking model hallucination rates?', '["Integrate human feedback loops into the application, allowing users to flag incorrect responses, and store these flags in Amazon DynamoDB for analysis.","Configure Amazon CloudWatch Alarms to trigger when the number of LLM invocations exceeds a predefined threshold, indicating high usage.","Use AWS X-Ray to trace the execution path of requests that result in hallucinations, identifying the specific service causing the issue.","Implement automated content moderation using Amazon Rekognition to detect inappropriate or hallucinated content in the chatbot''s responses."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) involves integrating human feedback loops into the application, allowing users to flag incorrect responses, and storing these flags in Amazon DynamoDB for analysis. Hallucinations are subjective and context-dependent, making human review the most reliable method for identification. Storing this feedback in DynamoDB allows for quantification and analysis over time to track hallucination rates and identify patterns for model improvement. Option B (incorrect) monitors LLM invocation rates, which is a cost or performance metric, not directly related to detecting content quality issues like hallucinations. Option C (incorrect) uses AWS X-Ray for tracing, which helps identify performance bottlenecks or errors in the application flow, but it cannot inherently detect the factual correctness of generated content. Option D (incorrect) uses Amazon Rekognition, which is designed for image and video analysis, not for detecting factual inaccuracies or hallucinations in text-based GenAI outputs.', 67, 'm_67_3', 9, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application processes user prompts and generates content. The development team wants to understand the end-to-end flow of requests, including the time spent in different components like prompt processing, LLM invocation, and post-processing. This is crucial for performance optimization and debugging. Which AWS service is best suited to GAIN end-to-end request tracing visibility?', '["Amazon CloudWatch Logs, by aggregating all application logs and searching for specific request IDs.","AWS X-Ray, by instrumenting the application code to capture traces across various AWS services and custom components.","Amazon CloudWatch Metrics, by creating custom metrics for each stage of the request processing pipeline.","Amazon S3, by storing detailed request logs in separate files for each component and analyzing them offline."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS X-Ray, which is specifically designed for end-to-end request tracing. By instrumenting the application code, X-Ray can capture traces across various AWS services (like AWS Lambda, Amazon API Gateway, Amazon Bedrock) and custom components, providing a visual service map and detailed timeline of each request, including time spent in each segment. This is ideal for performance optimization and debugging. Option A (incorrect) uses Amazon CloudWatch Logs, which can store logs, but correlating logs across multiple services for a single request to understand end-to-end flow is complex and not its primary purpose. Option C (incorrect) uses Amazon CloudWatch Metrics, which provides aggregate performance data but does not offer the granular, per-request tracing and visualization needed to understand the end-to-end flow of a single request. Option D (incorrect) uses Amazon S3 for storing logs, which is suitable for archival, but offline analysis of separate log files does not provide real-time, integrated end-to-end tracing capabilities.', 67, 'm_67_3', 10, NULL, NULL),
  ('mock_64_all_1775005739332', 'A finance department is concerned about the costs associated with their new GenAI application. They need to set up alerts for sudden spikes in LLM invocation costs or token usage that exceed predefined thresholds. The solution should provide immediate notification to the finance team. Which combination of AWS services will effectively DETECT and alert on cost anomalies?', '["Use AWS Cost Explorer to manually review daily cost reports and identify anomalies.","Configure Amazon CloudWatch Alarms on custom metrics derived from application logs that track token usage.","Set up AWS Budgets with custom cost thresholds and configure notifications via Amazon SNS to alert the finance team.","Implement a serverless application using AWS Lambda to periodically query billing data and send email notifications if costs are high."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) involves setting up AWS Budgets with custom cost thresholds and configuring notifications via Amazon SNS. AWS Budgets is specifically designed for cost management and alerting. It allows you to set custom budgets for your AWS usage and receive alerts when actual or forecasted costs exceed your defined thresholds, making it ideal for detecting and alerting on cost anomalies directly to the finance team via Amazon SNS. Option A (incorrect) relies on manual review, which is reactive and not suitable for immediate detection and alerting on sudden spikes. Option B (incorrect) uses CloudWatch Alarms on custom metrics, which can track application-level metrics like token usage, but it requires significant custom implementation to correlate these with actual billing costs and might not capture all cost dimensions. Option D (incorrect) requires building a custom serverless application to query billing data, which introduces unnecessary operational overhead and complexity compared to the fully managed AWS Budgets service.', 67, 'm_67_3', 11, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application uses an agent that interacts with various tools to fulfill user requests. The development team needs to monitor the performance of these agents and tools, specifically tracking which tools are invoked, their success rates, and any errors encountered during tool execution. Which monitoring strategy is MOST effective for MONITORING agent and tool performance?', '["Use AWS X-Ray to trace the execution of individual tool invocations and analyze their latency and success status.","Configure Amazon CloudWatch Alarms to trigger when the overall application latency exceeds a certain threshold.","Capture agent and tool invocation details in application logs, process these logs with AWS Lambda, and publish custom metrics to Amazon CloudWatch.","Periodically review the agent''s internal state and tool usage by connecting directly to the agent''s runtime environment."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes capturing agent and tool invocation details in application logs, processing these logs with AWS Lambda, and publishing custom metrics to Amazon CloudWatch. This is the most effective strategy because agent and tool performance details are often specific to the application''s internal logic. By logging these events, a Lambda function can parse the logs, extract relevant data (e.g., tool name, success/failure, duration), and then publish these as custom metrics to CloudWatch. This provides granular, quantifiable data for monitoring and analysis. Option A (incorrect) uses AWS X-Ray, which is excellent for tracing, but for aggregate performance metrics like success rates and specific tool usage, custom metrics are often more direct and easier to query. X-Ray provides individual trace details, not aggregate counts and rates. Option B (incorrect) monitors overall application latency, which is a high-level metric and does not provide specific insights into individual agent or tool performance. Option D (incorrect) involves periodically reviewing the agent''s internal state, which is a manual, non-scalable, and intrusive approach unsuitable for continuous monitoring in a production environment.', 67, 'm_67_3', 12, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company has deployed a Retrieval Augmented Generation (RAG) application. They need to monitor the quality of the retrieved documents and the relevance of the generated responses. This involves analyzing the interaction between the retrieval component and the LLM. Which approach is MOST effective for ASSESSING retrieval and generation quality?', '["Implement a continuous integration/continuous delivery (CI/CD) pipeline to automatically deploy new model versions.","Use Amazon CloudWatch to monitor the CPU and memory utilization of the underlying EC2 instances hosting the RAG application.","Capture and store user prompts, retrieved documents, and generated responses, then use a combination of automated evaluation metrics and human review to assess relevance and quality.","Configure Amazon S3 lifecycle policies to archive old RAG application logs to Amazon Glacier for long-term storage."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) involves capturing and storing user prompts, retrieved documents, and generated responses, then using a combination of automated evaluation metrics and human review to assess relevance and quality. This is the most effective approach because RAG quality is inherently subjective and requires evaluating both the accuracy of retrieval and the coherence/relevance of generation. Automated metrics can provide initial quantitative insights, but human review is crucial for nuanced quality assessment and identifying subtle issues. Option A (incorrect) describes a CI/CD pipeline, which is for deployment automation, not for monitoring application quality. Option B (incorrect) monitors infrastructure resource utilization, which is important for performance but does not provide insights into the quality or relevance of the GenAI output. Option D (incorrect) describes log archival, which is a data management strategy and not a method for actively assessing the quality of the RAG application''s output.', 67, 'm_67_3', 13, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application is used for internal document summarization. The operations team needs a centralized dashboard to visualize key metrics such as daily token consumption, average response latency, and error rates across all GenAI endpoints. Which AWS service provides the most efficient way to create a CENTRALIZED visualization of GenAI metrics?', '["Develop a custom web application hosted on Amazon EC2 to display metrics retrieved from various sources.","Utilize Amazon CloudWatch Dashboards to consolidate and visualize metrics, including those from Amazon Bedrock and custom application metrics.","Export all metrics to Amazon S3 and use Amazon QuickSight to create business intelligence reports.","Configure AWS Systems Manager Explorer to gather operational data and display it in a centralized view."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is to utilize Amazon CloudWatch Dashboards. CloudWatch Dashboards are specifically designed to consolidate and visualize operational metrics, including those automatically emitted by AWS services like Amazon Bedrock, and custom metrics published from application logs or other sources. They provide a centralized, real-time view with minimal setup and operational overhead. Option A (incorrect) requires developing and maintaining a custom web application on Amazon EC2, which introduces significant development and operational overhead compared to a managed dashboard service. Option C (incorrect) involves exporting metrics to Amazon S3 and using Amazon QuickSight, which is suitable for business intelligence and deep analytical reporting, but less ideal for real-time operational dashboards. Option D (incorrect) uses AWS Systems Manager Explorer, which provides an operational data view for resources but is not primarily designed for flexible, custom metric visualization dashboards like CloudWatch Dashboards.', 67, 'm_67_3', 14, NULL, NULL);

