INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A GenAI application provides real-time content generation, and users are reporting high latency. The development team identifies that the LLM inference is the bottleneck. They need to optimize the inference process to reduce the time taken for the model to generate a response. Which parameter tuning strategy is MOST effective for MINIMIZING LLM inference latency?', '["Increase the ''max_tokens_to_sample'' parameter to allow the model to generate longer, more detailed responses.","Decrease the ''temperature'' parameter to make the model''s output more deterministic and less creative.","Reduce the ''top_p'' parameter to narrow the sampling pool, making the model''s choices more focused and potentially faster.","Increase the ''top_k'' parameter to expand the number of possible next tokens considered, improving response diversity."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to reduce the ''top_p'' parameter. Reducing ''top_p'' (and ''top_k'') narrows the sampling pool of possible next tokens, which can make the model''s choices more focused and potentially reduce the computational effort required for sampling, thereby minimizing inference latency. Option A (incorrect) increases ''max_tokens_to_sample'', which directly increases the length of the generated response and thus increases latency, as the model has to generate more tokens. Option B (incorrect) decreases ''temperature'', which makes the model''s output more deterministic but doesn''t inherently reduce the time it takes to generate each token; its primary effect is on creativity, not direct latency. Option D (incorrect) increases ''top_k'', which expands the sampling pool, potentially increasing the computational burden and thus latency, while its primary goal is to improve response diversity.', 67, 'm_67_2', 15, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is building a GenAI application that generates long-form content, such as articles or reports. Users find it frustrating to wait for the entire response to be generated before seeing any output. They want to improve the user experience by displaying content as it becomes available. Which architectural pattern should they implement to IMPROVE perceived latency for long responses?', '["Implement a batch processing system using Amazon SQS and AWS Lambda to generate content in the background and notify users upon completion.","Increase the provisioned throughput of the LLM endpoint to ensure faster overall generation time for the complete response.","Utilize response streaming, where the LLM''s output is sent back to the client incrementally as it is generated, often facilitated by services like Amazon API Gateway.","Cache common long-form responses in Amazon DynamoDB to avoid re-generating them for identical prompts."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to utilize response streaming, where the LLM''s output is sent back to the client incrementally as it is generated, often facilitated by services like Amazon API Gateway. This pattern significantly improves perceived latency because users see content appearing in real-time, rather than waiting for the entire response. Option A (incorrect) describes a batch processing system, which would increase the actual latency for the user, as they would have to wait for a notification, not see content incrementally. Option B (incorrect) increases provisioned throughput, which reduces the total generation time but does not address the perceived latency issue of waiting for the entire response to be ready before display. Option D (incorrect) caches common responses, which helps for repetitive queries but does not improve the perceived latency for unique, long-form content that must be generated from scratch.', 67, 'm_67_2', 16, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application experiences unpredictable traffic patterns, with sudden surges in user requests. The current infrastructure struggles to scale quickly enough, leading to increased latency and failed requests during peak times. The team needs an automated solution to handle these traffic spikes efficiently. Which approach will ENSURE high throughput during traffic spikes with minimal operational effort?', '["Configure Amazon SageMaker Endpoints with autoscaling policies based on utilization metrics to automatically adjust the number of instances.","Manually provision a large number of Amazon EC2 instances to handle the maximum anticipated peak load at all times.","Implement a queueing mechanism using Amazon SQS to buffer incoming requests and process them at a fixed rate.","Use AWS Lambda functions for all GenAI inference, relying on Lambda''s inherent scaling capabilities without further configuration."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is to configure Amazon SageMaker Endpoints with autoscaling policies based on utilization metrics. This is the most effective and operationally efficient solution for handling unpredictable traffic spikes. SageMaker autoscaling automatically adjusts the number of instances based on demand, ensuring high throughput during peaks and scaling down during lulls, all with minimal manual intervention. Option B (incorrect) involves manual provisioning, which is not cost-effective (over-provisioning) and still requires manual intervention to adjust to actual demand. Option C (incorrect) uses a queueing mechanism, which can prevent request failures but introduces latency for users during peak times as requests wait in the queue, failing the ''high throughput'' and efficiency constraint. Option D (incorrect) relies on AWS Lambda''s inherent scaling, which is good for many workloads, but for GenAI inference, especially with larger models, SageMaker Endpoints with optimized instance types and autoscaling provide more control and often better performance characteristics for sustained high throughput.', 67, 'm_67_2', 17, NULL, NULL),
  ('mock_64_all_1775005739332', 'A RAG-based GenAI application is performing poorly due to slow retrieval of context documents. The vector database queries are taking too long, impacting the overall response time of the LLM. The team needs to improve the efficiency of the document retrieval process. Which optimization strategy is MOST effective for OPTIMIZING retrieval latency for RAG applications?', '["Increase the ''temperature'' parameter of the LLM to encourage more creative and diverse responses, reducing reliance on retrieved documents.","Optimize the indexing strategy of the vector database, ensure appropriate instance sizing, and consider using a more efficient embedding model for document chunks.","Implement a semantic caching layer for LLM responses, avoiding the need to retrieve documents for repetitive queries.","Switch from a RAG architecture to a pure fine-tuning approach, embedding all knowledge directly into the LLM."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is to optimize the indexing strategy of the vector database, ensure appropriate instance sizing, and consider using a more efficient embedding model for document chunks. Retrieval latency in RAG applications is directly tied to the performance of the vector database and the quality of the embeddings. Optimizing these components directly addresses the bottleneck. Option A (incorrect) tunes the LLM''s generation behavior and has no direct impact on the retrieval latency of the vector database. Option C (incorrect) implements semantic caching for LLM responses, which reduces LLM invocations but does not improve the underlying retrieval latency when a cache miss occurs. Option D (incorrect) suggests a fundamental architectural change from RAG to fine-tuning, which is a different approach with its own tradeoffs (e.g., knowledge freshness, cost) and doesn''t directly optimize the *retrieval* component of a RAG system.', 67, 'm_67_2', 18, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application processes multiple independent user prompts concurrently. The current architecture processes them sequentially, leading to high overall latency when many users are active. The team wants to process these prompts simultaneously to reduce total processing time. Which architectural pattern should be implemented to MAXIMIZE concurrent prompt processing?', '["Increase the batch size for individual LLM invocations, processing multiple prompts within a single request to the model.","Implement a single-threaded processing queue using Amazon SQS to ensure prompts are handled in a strict first-in, first-out order.","Utilize parallel processing by distributing incoming prompts across multiple AWS Lambda invocations or SageMaker endpoint instances.","Configure the LLM to generate shorter responses, thereby reducing the processing time for each individual prompt."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to utilize parallel processing by distributing incoming prompts across multiple AWS Lambda invocations or SageMaker endpoint instances. This directly addresses the need to process prompts simultaneously, maximizing concurrency and reducing overall processing time when many users are active. AWS Lambda and SageMaker Endpoints are designed to scale horizontally to handle concurrent requests. Option A (incorrect) increases the batch size, which can improve throughput for a single LLM invocation but doesn''t inherently maximize concurrency for *independent* user prompts, as it still processes them in batches rather than truly in parallel from the user''s perspective. Option B (incorrect) uses a single-threaded queue, which explicitly enforces sequential processing and would worsen overall latency for concurrent users. Option D (incorrect) reduces response length, which speeds up individual prompts but does not enable simultaneous processing of multiple independent prompts.', 67, 'm_67_2', 19, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application is deployed on Amazon SageMaker endpoints. The development team needs to evaluate different model configurations and inference parameters (e.g., temperature, top-p) to find the optimal balance between response quality and latency. This requires systematic testing. Which AWS service is best suited for SYSTEMATICALLY evaluating model performance through controlled experiments?', '["Manually deploy different model versions to separate SageMaker endpoints and compare their performance by observing logs.","Use Amazon CloudWatch to monitor the CPU and memory usage of the SageMaker endpoints during inference.","Leverage Amazon SageMaker Experiments to track, compare, and analyze model training and inference jobs with different parameter sets.","Implement a custom A/B testing framework on Amazon EC2 to route traffic to different model versions and collect user feedback."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to leverage Amazon SageMaker Experiments. SageMaker Experiments is specifically designed to help data scientists and developers track, compare, and analyze different model training and inference jobs. It allows for systematic evaluation of various model configurations and inference parameters, making it ideal for finding the optimal balance between quality and latency through controlled experiments. Option A (incorrect) involves manual deployment and observation, which is not systematic, scalable, or efficient for rigorous experimentation. Option B (incorrect) monitors infrastructure metrics, which are important for resource utilization but do not directly evaluate the quality or specific performance characteristics (like latency vs. temperature) of the model''s output. Option D (incorrect) involves building a custom A/B testing framework on Amazon EC2, which introduces significant development and operational overhead compared to the managed capabilities of SageMaker Experiments.', 67, 'm_67_2', 20, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application is designed to handle a large volume of requests, but the underlying LLM inference is resource-intensive. The team wants to ensure that the application can sustain high request rates without degradation in latency, even under heavy load. Which SageMaker endpoint feature should be used to SUSTAIN high throughput with consistent latency?', '["Configure the SageMaker Real-Time Endpoint with Provisioned Throughput and enable autoscaling to manage demand fluctuations.","Utilize SageMaker Asynchronous Inference to process requests in batches, which inherently provides consistent latency under heavy load.","Implement a client-side retry mechanism to re-submit failed requests, ensuring eventual consistency in throughput.","Decrease the ''max_tokens_to_sample'' parameter to reduce the computational burden on the LLM, thereby improving throughput."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is to configure the SageMaker Real-Time Endpoint with Provisioned Throughput and enable autoscaling. Provisioned Throughput ensures a baseline level of consistent, low-latency inference capacity for critical workloads, while autoscaling dynamically adjusts additional capacity to handle spikes above the provisioned baseline. This combination is ideal for sustaining high request rates with consistent latency under heavy and fluctuating loads. Option B (incorrect) uses SageMaker Asynchronous Inference, which is for non-real-time, large payload processing, not for sustaining consistent low latency for interactive requests. Its batching nature can introduce latency. Option C (incorrect) implements a client-side retry mechanism, which handles failures but does not prevent latency degradation or sustain throughput under heavy load; it''s a resilience pattern, not a performance optimization for the endpoint itself. Option D (incorrect) decreases ''max_tokens_to_sample'', which reduces the length of responses and might improve individual prompt latency, but it doesn''t directly ensure sustained high throughput for a large volume of requests or consistent latency under heavy load across the entire endpoint.', 67, 'm_67_2', 21, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 21
WHERE id = 'mock_64_all_1775005739332';

