  NOW()
)
ON CONFLICT (id) DO NOTHING;

-- ─────────────────────────────────────────
-- Module: m_68_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A development team is building a Retrieval Augmented Generation (RAG) application using Amazon Bedrock and needs to evaluate the quality of generated responses, specifically focusing on the relevance of retrieved documents and the factual accuracy of the generated answer based on those documents. They want an automated, scalable approach to provide continuous feedback during development. Which evaluation strategy should they implement?', '["Implement RAG-specific metrics like context relevance, groundedness, and faithfulness using an LLM-as-a-judge framework.","Conduct manual review sessions with subject matter experts to score each generated response for accuracy and relevance.","Set up A/B testing to compare user satisfaction with different RAG model outputs in a production environment.","Use a simple LLM-as-a-judge to rate the overall fluency and coherence of the generated text without specific RAG metrics."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the need for automated, scalable evaluation of RAG components by using specific metrics like context relevance, groundedness, and faithfulness. These metrics are designed to assess the quality of retrieval and generation in RAG systems, often implemented via an LLM-as-a-judge framework for continuous feedback. Option B (incorrect) is a manual process and does not meet the requirement for an automated and scalable approach. Option C (incorrect) is suitable for user preference and engagement in a production environment, but not for continuous, automated technical evaluation during development of RAG quality. Option D (incorrect) focuses on general text quality metrics and lacks the specific RAG-centric evaluation needed to assess retrieved document relevance and factual accuracy based on those documents.', 68, 'm_68_1', 1, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is deploying a new generative AI model for customer support and wants to compare its performance against an existing model. They need to gather human feedback efficiently on aspects like helpfulness, coherence, and conciseness, and integrate this feedback into their continuous integration/continuous delivery (CI/CD) pipeline for model improvement. Which approach is MOST suitable for this requirement?', '["Manually track feedback from customer service agents in a shared spreadsheet and periodically review it.","Utilize Amazon SageMaker Ground Truth to create human review workflows for model outputs, integrating feedback into retraining pipelines.","Implement A/B testing to measure which model leads to higher customer satisfaction scores over a long period.","Deploy an LLM-as-a-judge system to automatically score model outputs based on predefined rubrics for helpfulness and coherence."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes Amazon SageMaker Ground Truth, which is specifically designed for creating human labeling workflows. This makes it ideal for efficiently gathering structured human feedback on model outputs (like helpfulness, coherence, conciseness) and integrating this feedback into CI/CD pipelines for model improvement. Option A (incorrect) is a manual, inefficient process that does not scale and lacks structured integration into a CI/CD pipeline. Option C (incorrect) is good for measuring overall user satisfaction in production but doesn''t provide granular, structured feedback on specific aspects like coherence or conciseness in a way that directly feeds into model retraining for specific improvements. Option D (incorrect) uses an automated LLM-as-a-judge, which can be useful, but it lacks the nuance and specific human understanding required for subjective aspects of customer support quality, and the prompt specifically asks for *human feedback*.', 68, 'm_68_1', 2, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application generates creative marketing copy for various campaigns. The team wants to ensure the output maintains a consistent brand voice and style, and strictly avoids generating inappropriate or off-brand content. They need an automated mechanism to flag outputs that deviate significantly from established guidelines before they reach end-users, minimizing manual review. Which evaluation method should be implemented?', '["Rely on manual review by a dedicated content moderation team to check all generated marketing copy for brand consistency and safety.","Implement A/B testing to present different generated copies to a small user group and gather their preferences on brand voice.","Develop automated quality gates using custom evaluation scripts and content moderation services to check for brand guidelines and inappropriate content.","Use a simple sentiment analysis model to ensure the generated copy has a positive tone, assuming it will align with brand voice."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes the implementation of automated quality gates using custom evaluation scripts and content moderation services. This approach directly addresses the need for an automated mechanism to check for brand consistency, style adherence, and inappropriate content, minimizing manual review before content reaches end-users. Option A (incorrect) is a manual process, which the requirement explicitly seeks to minimize. Option B (incorrect) is for user preference and engagement, not for enforcing strict brand guidelines or content safety as an automated gate. Option D (incorrect) is too simplistic; sentiment analysis alone cannot guarantee brand voice consistency or detect all forms of inappropriate content effectively.', 68, 'm_68_1', 3, NULL, NULL),
  ('mock_64_all_1775005739332', 'A data science team is experimenting with different foundation models (FMs) from Amazon Bedrock for a text summarization task. They need a systematic way to compare the FMs based on objective metrics like ROUGE scores for summarization quality and perplexity for fluency, without significant manual effort. Which evaluation strategy would best meet these requirements?', '["Conduct extensive manual side-by-side comparisons of summaries generated by each model, relying on human judgment.","Implement A/B testing in a production environment to gather user feedback on the perceived quality of summaries from different FMs.","Focus solely on prompt engineering techniques to optimize the input for each FM, assuming the best prompt will reveal the best model.","Utilize automated evaluation pipelines with established metrics such as ROUGE for content overlap and perplexity for language fluency."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) directly addresses the need for systematic, objective, and automated comparison of foundation models using established metrics like ROUGE (for summarization quality/content overlap) and perplexity (for fluency). This approach minimizes manual effort and provides quantitative data for model comparison. Option A (incorrect) is a manual process and does not meet the ''without significant manual effort'' constraint. Option B (incorrect) is for user preference in a production setting, not for objective, automated evaluation during model experimentation. Option C (incorrect) focuses on input optimization rather than objective evaluation of the models themselves, and does not provide a comparative metric for different FMs.', 68, 'm_68_1', 4, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application assists legal professionals by generating draft legal documents. Ensuring factual accuracy and adherence to specific legal terminology is paramount. The team wants to implement an evaluation system that can automatically assess the factual correctness of generated content against a known corpus of legal texts and identify any deviations from standard legal phrasing. Which evaluation approach is MOST appropriate?', '["Develop an automated RAG assessment framework that checks for groundedness against the legal corpus and uses custom metrics for terminology adherence.","Rely solely on expert legal professionals to manually review every generated document for accuracy and terminology.","Implement A/B testing to see which generated document styles are preferred by legal professionals.","Use a general-purpose LLM-as-a-judge to rate the overall readability and coherence of the legal documents."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate approach. Developing an automated RAG assessment framework that checks for groundedness against a legal corpus directly addresses the need for factual accuracy, while custom metrics can be designed to ensure adherence to specific legal terminology. This provides an automated and scalable solution. Option B (incorrect) is a manual process and does not meet the requirement for an automated system. Option C (incorrect) focuses on stylistic preference, not factual accuracy or terminology adherence. Option D (incorrect) uses a general LLM-as-a-judge for readability and coherence, which are important, but it does not specifically guarantee factual accuracy or correct legal terminology against a known corpus.', 68, 'm_68_1', 5, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is developing a conversational AI agent using Amazon Bedrock. Before deploying new iterations, they need to validate that the agent''s responses are relevant to user queries and coherent in conversation flow. They want to use a technique that simulates user interaction with synthetic test cases and provides quantitative scores for these aspects. Which evaluation method should they choose?', '["Conduct extensive manual testing by human testers engaging in free-form conversations with the agent.","Implement an LLM-as-a-judge system to evaluate agent responses against predefined criteria for relevance and coherence using synthetic dialogues.","Deploy the new agent version to a small group of beta users and collect their qualitative feedback on conversation quality.","Use traditional keyword matching algorithms to check if the agent''s responses contain relevant terms from the user''s query."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes using an LLM-as-a-judge system to evaluate agent responses with synthetic dialogues, providing quantitative scores for relevance and coherence. This approach directly meets the need for automated, quantitative validation of conversational agent performance before deployment. Option A (incorrect) is a manual process and does not provide quantitative scores efficiently. Option C (incorrect) involves live user testing, which is typically done later in the development cycle, and primarily yields qualitative feedback. Option D (incorrect) is a simplistic approach that cannot effectively assess the nuance of conversational relevance or coherence.', 68, 'm_68_1', 6, NULL, NULL),
  ('mock_64_all_1775005739332', 'A marketing team uses a GenAI model to generate email subject lines. They want to optimize for open rates and click-through rates. They need an evaluation strategy that directly measures user engagement with different generated subject lines in a production environment to determine the most effective variant. Which evaluation method is MOST suitable?', '["Use an LLM-as-a-judge to score the creativity and appeal of different subject lines based on internal guidelines.","Conduct human review sessions where a panel of marketing experts rates the potential effectiveness of each subject line.","Implement A/B testing to send different subject lines to segments of the target audience and measure actual open and click-through rates.","Calculate ROUGE scores to assess the similarity of generated subject lines to a set of high-performing historical subject lines."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the most suitable approach because A/B testing directly measures user engagement (open rates, click-through rates) in a production environment, providing empirical data on the most effective subject lines. This aligns perfectly with the goal of optimizing for these metrics. Option A (incorrect) uses an LLM-as-a-judge, which provides subjective scores based on predefined criteria, but does not measure actual user behavior. Option B (incorrect) relies on expert opinion, which can be valuable but is not a direct measure of user engagement and is not scalable. Option D (incorrect) uses ROUGE scores, which measure text similarity, not user engagement or effectiveness for marketing goals.', 68, 'm_68_1', 7, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application provides personalized product recommendations based on user preferences and historical data. The team needs to evaluate if the generated recommendations are truly relevant to individual user profiles and if they accurately reflect the user''s implicit and explicit interests. They want an automated system that can assess the "personalization" aspect without relying solely on human review. Which evaluation strategy should they employ?', '["Conduct extensive manual user surveys to gather feedback on the perceived personalization of recommendations.","Implement a general sentiment analysis model to ensure the recommendations have a positive tone.","Develop custom evaluation metrics that compare generated recommendations against known user preferences and historical interactions, potentially using an LLM-as-a-judge with user context.","Set up A/B testing to measure which recommendation strategy leads to higher overall conversion rates."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) directly addresses the need for automated evaluation of personalization relevance by developing custom metrics that compare recommendations against known user preferences and historical data. Using an LLM-as-a-judge with user context can further enhance this by providing a nuanced assessment of personalization. Option A (incorrect) is a manual process and does not meet the requirement for an automated system. Option B (incorrect) is too simplistic; sentiment analysis does not assess personalization or relevance to specific user data. Option D (incorrect) measures overall business impact (conversion rates) but doesn''t provide granular, automated feedback on the *quality* of personalization itself for continuous improvement.', 68, 'm_68_1', 8, NULL, NULL),
  ('mock_64_all_1775005739332', 'A content creation platform uses a GenAI model to generate blog post outlines. The team needs to ensure the outlines are comprehensive, logically structured, and cover key topics identified from source material. They want to implement an automated quality gate that can check for these structural and content coverage aspects before an editor reviews them. Which evaluation approach is MOST appropriate?', '["Implement automated quality gates using custom scripts to check for section headings, sub-points, and keyword presence, potentially with an LLM-as-a-judge for logical flow.","Rely solely on manual editorial review by human content specialists to assess the quality of each generated outline.","Deploy A/B testing to determine which outline structure leads to higher engagement from blog readers.","Use a simple word count metric to ensure the outlines meet a minimum length requirement."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) describes implementing automated quality gates with custom scripts to check for structural elements (section headings, sub-points) and content coverage (keyword presence), augmented by an LLM-as-a-judge for subjective aspects like logical flow. This directly addresses the need for an automated system to ensure comprehensiveness and logical structure. Option B (incorrect) is a manual process, which the requirement seeks to automate as a quality gate. Option C (incorrect) is for measuring user engagement in a production environment, not for pre-editor quality checks on structure and content. Option D (incorrect) is a very basic metric that does not assess comprehensiveness, logical structure, or topic coverage.', 68, 'm_68_1', 9, NULL, NULL),
  ('mock_64_all_1775005739332', 'A financial institution is using a GenAI model to summarize complex financial reports. They need to ensure the summaries are accurate, concise, and do not introduce any hallucinations. They want to establish a robust evaluation process that combines automated metrics with expert human review for critical outputs. Which strategy best meets this requirement?', '["Rely solely on automated ROUGE scores to measure content overlap with the original reports, assuming high scores imply accuracy.","Implement a multi-stage evaluation process combining automated quality gates (e.g., ROUGE, factual consistency checks) with a human feedback loop for expert review of critical summaries.","Conduct A/B testing to compare user satisfaction with summaries generated by different models.","Increase the model''s temperature parameter to encourage more creative and concise summaries."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a robust evaluation process by combining automated quality gates (like ROUGE for conciseness/content overlap and factual consistency checks for accuracy/hallucinations) with a human feedback loop for expert review. This hybrid approach ensures both scalability and the necessary human oversight for critical financial documents. Option A (incorrect) relies solely on automated metrics, which might not fully capture nuances of accuracy or detect subtle hallucinations, especially in critical domains like finance. Option C (incorrect) measures user satisfaction, not the factual accuracy or conciseness required for financial reports. Option D (incorrect) is a model parameter adjustment that might affect conciseness but does not constitute an evaluation strategy and could worsen factual accuracy or introduce hallucinations.', 68, 'm_68_1', 10, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company is developing a Retrieval Augmented Generation (RAG) application using Amazon Bedrock and Amazon OpenSearch Service. Before deploying to production, the team needs to evaluate the relevance and factual accuracy of the generated responses while minimizing manual effort. They have a small set of ground truth data for critical scenarios. Which approach effectively meets this requirement with the LEAST manual effort?', '["Implement automated RAG evaluation metrics (e.g., faithfulness, answer relevance) using a custom evaluation pipeline in Amazon SageMaker, supplemented by a targeted human review process for a small percentage of high-confidence flagged responses.","Conduct extensive A/B testing in a production-like environment with real user traffic, collecting implicit feedback on user satisfaction and response quality over several weeks.","Manually review every generated response from the RAG application against the ground truth data, logging discrepancies in an Amazon S3 bucket for later analysis.","Configure an LLM-as-a-judge system using a separate, larger foundational model to score the RAG application''s responses for relevance and accuracy, without any human intervention."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) provides the most efficient balance. Automated RAG evaluation metrics, such as faithfulness (how well the answer is supported by retrieved context) and answer relevance (how relevant the answer is to the question), can be implemented programmatically in a SageMaker pipeline. This significantly reduces the need for extensive manual review. Supplementing this with a targeted human review for edge cases or flagged responses ensures high quality without overwhelming human evaluators, thus minimizing manual effort. Option B (incorrect) involves A/B testing in a production-like environment, which is suitable for post-deployment optimization but not for pre-production evaluation where a baseline of quality needs to be established efficiently and with minimal manual effort. It also relies on implicit feedback, which might not directly measure factual accuracy. Option C (incorrect) describes a purely manual review process for every response, which is highly labor-intensive and directly contradicts the ''LEAST manual effort'' constraint. Option D (incorrect) suggests using an LLM-as-a-judge without human intervention. While LLM-as-a-judge can be powerful, relying solely on it without any ground truth validation or human oversight can introduce biases or inaccuracies from the judging LLM itself, especially for factual accuracy, and might not be sufficient for critical pre-production validation.', 68, 'm_68_1', 11, NULL, NULL),
  ('mock_64_all_1775005739332', 'A company has deployed a generative AI chatbot for customer support, built on Amazon Bedrock. They need to continuously monitor its performance to identify instances where the chatbot generates unhelpful or incorrect information, establishing a feedback loop for improvement. The primary constraint is to achieve this with MINIMAL operational overhead. Which solution is most appropriate?', '["Develop a complex A/B testing framework to continuously compare different chatbot versions in production, manually analyzing user transcripts for quality degradation.","Implement a human feedback loop using Amazon Augmented AI (A2I) to review a subset of conversations flagged by users or automated heuristics, combined with automated metrics and anomaly detection from Amazon CloudWatch logs.","Rely solely on end-user surveys and satisfaction ratings collected after each conversation, manually aggregating and reviewing feedback weekly.","Periodically retrain the foundational model with new data, assuming that model updates will inherently resolve issues without specific monitoring for unhelpful responses."]'::jsonb, 'mcq', '{2}'::integer[], 'Option B (correct) offers the most effective solution with minimal operational overhead. By using Amazon Augmented AI (A2I), the company can efficiently route a small, targeted subset of conversations (flagged by users or simple automated rules, e.g., negative sentiment) to human reviewers. This provides high-quality, targeted feedback without requiring humans to review every interaction. Complementing this with automated metrics and anomaly detection in Amazon CloudWatch on Bedrock logs allows for continuous, low-overhead monitoring of overall performance trends and potential issues. Option A (incorrect) suggests a complex A/B testing framework coupled with manual transcript analysis. This approach is high in operational overhead due to continuous testing and manual review, which contradicts the ''MINIMAL operational overhead'' constraint. Option C (incorrect) relies solely on end-user surveys. While useful, surveys provide lagging indicators and may not capture specific instances of unhelpful or incorrect information in real-time, nor do they offer a direct feedback loop for improvement. It also lacks automated monitoring. Option D (incorrect) assumes that retraining the model will automatically resolve issues. This is a reactive approach that lacks continuous monitoring and a specific feedback mechanism to identify and address unhelpful or incorrect responses, making it inefficient for continuous improvement.', 68, 'm_68_1', 12, NULL, NULL),
  ('mock_64_all_1775005739332', 'A RAG-based generative AI application, built on Amazon Bedrock and utilizing Amazon OpenSearch Service for document retrieval, frequently provides irrelevant answers or hallucinates information. The development team suspects that the retrieval component is not consistently fetching the most pertinent documents for a given query. They need to diagnose these retrieval failures efficiently. Which troubleshooting approach is most effective?', '["Increase the context window size of the foundational model in Amazon Bedrock, assuming that more context will compensate for poor retrieval.","Analyze detailed retrieval logs, including the input query, retrieved document IDs, their relevance scores, and the content snippets, stored in Amazon CloudWatch Logs or Amazon OpenSearch Service, comparing them against a golden dataset of expected retrievals for specific queries.","Re-embed all documents in the Amazon OpenSearch Service index without first analyzing the current retrieval patterns, hoping to improve document relevance.","Implement an A/B testing framework to compare different prompt engineering strategies for the foundational model, assuming the issue lies with the prompt rather than retrieval."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective and efficient approach for diagnosing retrieval failures. By analyzing detailed retrieval logs, which should include the original query, the IDs of the documents retrieved, their associated relevance scores, and potentially the actual content snippets, the team can directly observe what the retrieval component is returning. Comparing these logs against a golden dataset of queries with known correct retrievals allows for a systematic identification of where the retrieval mechanism is failing. This pinpoints whether the issue is with indexing, embedding, or the search algorithm itself. Option A (incorrect) attempts to compensate for poor retrieval by increasing the LLM''s context window. While this might sometimes mask retrieval issues, it doesn''t diagnose or solve the root cause of the retrieval failure and can lead to higher inference costs and potentially more context overflow issues. Option C (incorrect) suggests re-embedding all documents without prior analysis. This is a costly and time-consuming operation that might not solve the problem if the issue is with the retrieval logic or query processing, not the embeddings themselves. Option D (incorrect) focuses on prompt engineering. While prompts are critical, if the underlying retrieval is flawed, even the best prompt might not yield good results. This approach misdirects troubleshooting efforts away from the suspected retrieval problem.', 68, 'm_68_1', 13, NULL, NULL),
  ('mock_64_all_1775005739332', 'A generative AI application, built on Amazon Bedrock, integrates with several backend microservices via AWS Lambda functions to perform actions (tool use). Users occasionally experience errors where the agent fails to call the correct tool or misinterprets the tool''s output, leading to incorrect actions or responses. The team needs a systematic way to troubleshoot these integration errors efficiently. Which approach should they adopt?', '["Increase the temperature parameter of the foundational model in Amazon Bedrock to encourage more diverse tool-use attempts, hoping it will eventually find the correct path.","Implement detailed structured logging within the AWS Lambda functions and the Bedrock agent''s invocation logic, capturing tool call inputs, outputs, and any errors. Use AWS X-Ray for end-to-end tracing across the application and integrated services, and maintain a golden dataset for regression testing tool calls.","Manually inspect the final generated response from the Bedrock agent for errors, and if an error is found, manually re-run the process with different prompts until it works.","Retrain the foundational model with a larger dataset of successful tool-use examples, assuming that more training data will eliminate integration issues."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) provides a systematic and efficient troubleshooting approach. Implementing detailed structured logging within the AWS Lambda functions (which handle tool calls) and the Bedrock agent''s invocation logic allows the team to capture precise information about inputs, outputs, and any errors at each step of the tool-use process. AWS X-Ray provides end-to-end tracing, visualizing the flow of requests across the Bedrock agent and integrated Lambda functions, making it easy to pinpoint where failures occur. Maintaining a golden dataset of expected tool calls and their outcomes enables automated regression testing, quickly identifying if new changes introduce or reintroduce integration errors. Option A (incorrect) suggests increasing the model''s temperature. This might lead to more varied outputs but does not diagnose or resolve underlying issues with tool calling logic or integration errors; it could even exacerbate them by making the agent''s behavior less predictable. Option C (incorrect) describes a manual, reactive, and highly inefficient debugging process. It lacks systematic logging, tracing, or automated testing, making it unsuitable for complex integration troubleshooting. Option D (incorrect) proposes retraining the foundational model. While fine-tuning can improve tool-use capabilities, it''s a broad solution that doesn''t specifically target or diagnose integration errors between the agent and external services. Detailed logging and tracing are necessary to understand *why* the integration is failing, which then informs targeted model improvements or code fixes.', 68, 'm_68_1', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_68_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_64_all_1775005739332', 'A RAG-based GenAI application using Amazon Bedrock for text generation and Amazon OpenSearch Service for retrieval is experiencing issues where responses are often irrelevant or lack specific details. The development team suspects the retrieval component is failing to provide the most relevant context. Which troubleshooting step should they prioritize to diagnose this issue?', '["Analyze Amazon CloudWatch Logs and Amazon OpenSearch Service query logs to inspect the retrieved documents for relevance to the user''s query.","Adjust the Amazon Bedrock model''s temperature and top-p parameters to encourage more relevant text generation.","Increase the context window size for the Amazon Bedrock model to allow for more input tokens.","Implement A/B testing to compare user satisfaction with responses from different RAG configurations."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most direct and effective troubleshooting step. By analyzing Amazon CloudWatch Logs and Amazon OpenSearch Service query logs, the team can inspect the actual documents retrieved for a given query. This allows them to directly assess if the retrieval component is providing relevant context, which is the suspected root cause of irrelevant or lacking responses. Option B (incorrect) adjusts the generation behavior of the model, but won''t fix issues with the *retrieval* of context. Option C (incorrect) addresses context overflow, which is a different issue than irrelevant retrieval. Option D (incorrect) is an evaluation strategy, not a troubleshooting step to diagnose a specific technical failure.', 68, 'm_68_2', 15, NULL, NULL),
  ('mock_64_all_1775005739332', 'Users of a conversational AI agent powered by Amazon Bedrock are reporting that the agent frequently "forgets" previous parts of the conversation or provides generic answers despite a long conversation history. The team suspects the context window is being exceeded, leading to information loss. Which troubleshooting approach should they take to confirm and address this issue?', '["Troubleshoot embedding drift by re-evaluating the quality of the embedding model used for conversational history.","Analyze Amazon CloudWatch Logs to monitor the token count of input prompts, including conversation history, for specific interactions.","Optimize prompt engineering by making prompts shorter and more concise to reduce the overall token usage.","Check for retrieval failures in the knowledge base, assuming the agent is not finding relevant information."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the suspicion of context overflow. By analyzing Amazon CloudWatch Logs and monitoring the token count of input prompts (which include the conversation history), the team can confirm if the context window is indeed being exceeded for long conversations, leading to the ''forgetting'' behavior. Option A (incorrect) is for issues related to embedding quality over time, not typically for immediate context window overflow. Option C (incorrect) is a mitigation strategy, but not a direct troubleshooting step to *confirm* the context overflow issue. Option D (incorrect) focuses on retrieval, which is a different problem from the model losing track of its own conversational history due to context window limits.', 68, 'm_68_2', 16, NULL, NULL),
  ('mock_64_all_1775005739332', 'A GenAI application integrated with an external API for real-time data enrichment is intermittently failing to generate complete responses. The logs show occasional timeouts or malformed responses from the external service. The team needs to systematically identify the root cause of these integration errors. Which combination of AWS services would be MOST effective for diagnosing this problem?', '["Adjust the Amazon Bedrock model parameters, such as `max_tokens_to_sample`, to ensure complete responses.","Analyze prompt confusion by reviewing user prompts and model outputs for misinterpretations.","Use AWS X-Ray to trace requests across the application and external API calls, combined with Amazon CloudWatch Logs for detailed error messages.","Implement a custom Python script to periodically ping the external API and check its availability."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most effective combination for diagnosing intermittent integration errors. AWS X-Ray enables end-to-end tracing of requests, allowing the team to visualize the flow through the application and identify latency or failures specifically within the external API calls. Amazon CloudWatch Logs then provides detailed error messages and logs from both the application and potentially the API Gateway (if used) to pinpoint the exact nature of the malformed responses or timeouts. Option A (incorrect) addresses model generation parameters, not external API integration issues. Option B (incorrect) focuses on prompt interpretation, which is unrelated to external API failures. Option D (incorrect) is a basic availability check, but lacks the detailed tracing and logging capabilities needed to systematically identify the root cause of intermittent errors and malformed responses within the request flow.', 68, 'm_68_2', 17, NULL, NULL),
  ('mock_64_all_1775005739332', 'A development team is fine-tuning a foundational model (FM) on Amazon SageMaker for a specialized legal domain. They need to quickly compare the output quality, specifically focusing on fluency and coherence, between different fine-tuned model versions during their iterative development cycle. The goal is to achieve the FASTEST iteration cycle with automated feedback. Which solution should they implement?', '["Implement a system to log all model outputs to Amazon S3, then periodically run batch jobs on Amazon EC2 instances to calculate traditional NLP metrics like BLEU and ROUGE scores for comparison.","Utilize Amazon SageMaker Clarify or Amazon Bedrock evaluation jobs with custom LLM-as-a-judge metrics designed to assess fluency and coherence, integrating these evaluations into their CI/CD pipeline for automated feedback.","Deploy each new fine-tuned model version to a staging environment and conduct manual human review by domain experts, providing qualitative feedback on fluency and coherence.","Set up an A/B testing framework in a production environment, routing a small percentage of live traffic to each new model version and collecting implicit user satisfaction metrics."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the need for a fast iteration cycle with automated feedback. Amazon SageMaker Clarify or Amazon Bedrock evaluation jobs allow for programmatic evaluation of model outputs. By defining custom LLM-as-a-judge metrics for fluency and coherence, the team can automate the assessment process. Integrating this into a CI/CD pipeline ensures that every new model version is automatically evaluated, providing rapid feedback without human intervention, thus accelerating the iteration cycle. Option A (incorrect) relies on traditional NLP metrics like BLEU and ROUGE. While useful, these metrics often correlate poorly with human judgments of fluency and coherence for generative models and might not provide the nuanced feedback needed for fine-tuning. It also involves batch processing, which might not be the fastest for iterative development. Option C (incorrect) involves manual human review, which is inherently slow and does not provide automated feedback, making it unsuitable for the ''FASTEST iteration cycle'' constraint. Option D (incorrect) describes A/B testing in a production environment. This is a post-deployment strategy for optimizing user experience with live traffic, not an efficient method for rapid, automated quality comparison during the development and fine-tuning phase.', 68, 'm_68_2', 18, NULL, NULL),
  ('mock_64_all_1775005739332', 'Users of a conversational generative AI application, powered by Amazon Bedrock, frequently report that the model loses context in longer conversations, leading to repetitive or nonsensical responses. The development team suspects that the conversation history is exceeding the foundational model''s context window limits. Which solution will help identify and resolve these context overflow issues?', '["Increase the foundational model''s context window size indefinitely to accommodate all conversation history, regardless of cost implications.","Implement a mechanism to count tokens for both the input prompt and the accumulated conversation history, logging these token counts to Amazon CloudWatch, and using an AWS Lambda function to summarize or truncate the conversation history when approaching the model''s limits.","Fine-tune the foundational model with a larger dataset of long conversations, expecting it to inherently manage context better without explicit handling.","Rely solely on user feedback reports to identify when context is lost, then manually review conversation transcripts to diagnose the issue."]'::jsonb, 'mcq', '{2}'::integer[], 'Option B (correct) provides a robust and proactive solution to identify and resolve context overflow. By implementing token counting for both the current prompt and the entire conversation history, the application can monitor the actual token usage. Logging these metrics to Amazon CloudWatch provides visibility into when and how often context limits are being approached or exceeded. An AWS Lambda function can then be used to programmatically manage the conversation history, either by summarizing older turns or truncating them, ensuring that the input to the foundational model stays within its context window. Option A (incorrect) suggests increasing the context window indefinitely. This is often not feasible as models have fixed maximum context windows, and even if possible, it would significantly increase inference costs and latency without addressing the underlying management of conversation length. Option C (incorrect) proposes fine-tuning the model. While fine-tuning can improve a model''s understanding, it doesn''t inherently change the hard context window limit or provide a mechanism for managing conversation history that exceeds it. Explicit context management is still required. Option D (incorrect) relies on reactive user feedback and manual review. This is inefficient, slow, and does not provide a systematic or automated way to detect or prevent context overflow, leading to a poor user experience.', 68, 'm_68_2', 19, NULL, NULL);

